DROP TABLE IF EXISTS `ai_ab_test`;

CREATE TABLE `ai_ab_test` (
  `id` bigint(20) NOT NULL COMMENT '主键',
  `tenant_id` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT '000000' COMMENT '租户ID',
  `test_name` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '测试名称',
  `description` varchar(512) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '测试描述',
  `model_a_id` bigint(20) NOT NULL COMMENT '模型A的ID',
  `model_b_id` bigint(20) NOT NULL COMMENT '模型B的ID',
  `test_questions` text COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '测试问题列表（JSON数组）',
  `status` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT 'PENDING' COMMENT '状态：PENDING/RUNNING/COMPLETED',
  `result_summary` text COLLATE utf8mb4_unicode_ci COMMENT '结果摘要（JSON）',
  `create_dept` bigint(20) DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) DEFAULT NULL COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` bigint(20) DEFAULT NULL COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='AI A/B 测试';

DROP TABLE IF EXISTS `ai_ab_test_result`;

CREATE TABLE `ai_ab_test_result` (
  `id` bigint(20) NOT NULL COMMENT '主键',
  `tenant_id` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT '000000' COMMENT '租户ID',
  `test_id` bigint(20) NOT NULL COMMENT '测试ID',
  `question` varchar(512) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '测试问题',
  `model_id` bigint(20) NOT NULL COMMENT '模型ID',
  `model_name` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '模型名称',
  `response` text COLLATE utf8mb4_unicode_ci COMMENT '模型回答',
  `token_usage` int(11) DEFAULT NULL COMMENT 'Token 用量',
  `latency_ms` int(11) DEFAULT NULL COMMENT '响应延迟（毫秒）',
  `score` int(11) DEFAULT NULL COMMENT '人工评分（1-5）',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_test_id` (`test_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='AI A/B 测试结果';

DROP TABLE IF EXISTS `ai_config`;

CREATE TABLE `ai_config` (
  `config_group` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '配置分组: sql_safety/vector_store/web_search/flow/knowledge_graph',
  `config_value` json DEFAULT NULL COMMENT '配置值(分组内字段JSON)',
  `remark` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `create_dept` bigint(20) DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) DEFAULT NULL COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` bigint(20) DEFAULT NULL COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`config_group`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='AI运行参数配置(全局, 页面化替代nexus.ai yml运行参数)';


DROP TABLE IF EXISTS `ai_decision_action`;

CREATE TABLE `ai_decision_action` (
  `id` bigint(20) NOT NULL COMMENT '主键',
  `tenant_id` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '000000' COMMENT '租户编号',
  `run_id` bigint(20) NOT NULL COMMENT '决策运行ID',
  `action_type` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '动作类型',
  `title` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '动作标题',
  `display_reason` varchar(1000) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '展示理由',
  `target_biz_type` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '目标业务类型',
  `target_biz_id` bigint(20) DEFAULT NULL COMMENT '目标业务ID',
  `target_biz_code` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '目标业务编号',
  `payload_json` longtext COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '白名单动作参数JSON',
  `purchase_payload_version` tinyint(4) DEFAULT NULL COMMENT '采购动作载荷合同版本；NULL为旧合同，必须与run和冻结载荷校验',
  `risk_level` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '动作风险等级',
  `approval_required` char(1) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Y' COMMENT '是否需要审批',
  `approval_status` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '审批状态',
  `execution_status` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '执行状态',
  `permission_code` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '业务权限码',
  `executor_code` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '执行器编码',
  `sequence_no` int(11) NOT NULL DEFAULT '0' COMMENT '执行顺序',
  `dependency_ids_json` varchar(2000) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '依赖动作ID JSON',
  `idempotency_key` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '幂等键',
  `approved_by` bigint(20) DEFAULT NULL COMMENT '审批人',
  `approved_at` datetime DEFAULT NULL COMMENT '审批时间',
  `approval_comment` varchar(1000) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '审批意见',
  `result_biz_type` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '结果业务类型',
  `result_biz_id` bigint(20) DEFAULT NULL COMMENT '结果业务ID',
  `result_biz_code` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '结果业务编号',
  `result_json` longtext COLLATE utf8mb4_unicode_ci COMMENT '执行结果JSON',
  `retry_count` int(11) NOT NULL DEFAULT '0' COMMENT '重试次数',
  `last_error_code` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '最后错误码',
  `last_error_message` varchar(1000) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '最后脱敏错误',
  `started_at` datetime DEFAULT NULL COMMENT '执行开始时间',
  `finished_at` datetime DEFAULT NULL COMMENT '执行完成时间',
  `version` int(11) NOT NULL DEFAULT '0' COMMENT '乐观锁版本',
  `create_dept` bigint(20) DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) DEFAULT NULL COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` bigint(20) DEFAULT NULL COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `del_flag` char(1) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '0' COMMENT '删除标志',
  `attr1` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段1',
  `attr2` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段2',
  `attr3` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段3',
  `attr4` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段4',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uk_decision_action_idempotency` (`tenant_id`,`idempotency_key`) USING BTREE,
  KEY `idx_decision_action_run` (`run_id`,`sequence_no`) USING BTREE,
  KEY `idx_decision_action_approval` (`tenant_id`,`approval_status`) USING BTREE,
  KEY `idx_decision_action_execution` (`tenant_id`,`execution_status`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='AI工业决策动作';


DROP TABLE IF EXISTS `ai_decision_evidence`;

CREATE TABLE `ai_decision_evidence` (
  `id` bigint(20) NOT NULL COMMENT '主键',
  `tenant_id` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '000000' COMMENT '租户编号',
  `run_id` bigint(20) NOT NULL COMMENT '决策运行ID',
  `evidence_key` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '运行内证据键',
  `source_domain` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'ERP/MES/IOT/RAG/RULE/DERIVED',
  `source_type` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '来源类型',
  `source_id` bigint(20) DEFAULT NULL COMMENT '来源ID',
  `source_code` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '来源编号',
  `source_name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '来源名称',
  `metric_code` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '指标编码',
  `metric_name` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '指标名称',
  `value_type` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '值类型',
  `metric_value` varchar(2000) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '指标展示值',
  `unit` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '单位',
  `observed_at` datetime DEFAULT NULL COMMENT '观察时间',
  `data_version` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '数据版本',
  `confidence` decimal(5,4) DEFAULT NULL COMMENT '置信度',
  `verifiable` char(1) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Y' COMMENT '是否可验证',
  `normative` char(1) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'N' COMMENT '是否规范性证据',
  `derived_from_json` text COLLATE utf8mb4_unicode_ci COMMENT '派生来源证据键JSON',
  `display_path` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '前端业务跳转路径',
  `create_dept` bigint(20) DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) DEFAULT NULL COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` bigint(20) DEFAULT NULL COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `del_flag` char(1) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '0' COMMENT '删除标志',
  `attr1` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段1',
  `attr2` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段2',
  `attr3` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段3',
  `attr4` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段4',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uk_decision_evidence` (`run_id`,`evidence_key`) USING BTREE,
  KEY `idx_decision_evidence_source` (`tenant_id`,`source_type`,`source_id`) USING BTREE,
  KEY `idx_decision_evidence_run` (`run_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='AI工业决策证据';
















DROP TABLE IF EXISTS `ai_decision_run`;

CREATE TABLE `ai_decision_run` (
  `id` bigint(20) NOT NULL COMMENT '主键',
  `tenant_id` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '000000' COMMENT '租户编号',
  `scene_code` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '场景编码',
  `biz_type` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '业务类型',
  `biz_id` bigint(20) DEFAULT NULL COMMENT '根业务ID',
  `biz_code` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '根业务编号',
  `parent_run_id` bigint(20) DEFAULT NULL COMMENT '父运行ID',
  `superseded_by_run_id` bigint(20) DEFAULT NULL COMMENT '替代运行ID',
  `trigger_type` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '触发类型',
  `status` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '运行状态',
  `decision_contract_version` tinyint(4) DEFAULT NULL COMMENT '决策合同版本；NULL为旧合同，只有可信新版路径显式写2',
  `risk_score` decimal(8,2) DEFAULT NULL COMMENT '风险分数',
  `risk_level` varchar(16) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '风险等级',
  `confidence_level` varchar(16) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '置信度等级',
  `recommended_scenario_code` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '推荐方案编码',
  `input_snapshot_json` longtext COLLATE utf8mb4_unicode_ci COMMENT '输入快照JSON',
  `input_snapshot_hash` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '输入快照SHA-256',
  `snapshot_time` datetime DEFAULT NULL COMMENT '快照时间',
  `valid_until` datetime DEFAULT NULL COMMENT '审批有效截止时间',
  `score_config_json` text COLLATE utf8mb4_unicode_ci COMMENT '评分配置快照',
  `scenario_result_json` longtext COLLATE utf8mb4_unicode_ci COMMENT '场景推演结果',
  `narrative_json` longtext COLLATE utf8mb4_unicode_ci COMMENT '决策说明JSON',
  `result_json` longtext COLLATE utf8mb4_unicode_ci COMMENT '完整决策结果JSON',
  `outcome_json` longtext COLLATE utf8mb4_unicode_ci COMMENT '执行后结果JSON',
  `approval_context_json` longtext COLLATE utf8mb4_unicode_ci COMMENT '可信审批执行人权限快照（禁止从Flow输入恢复）',
  `summary_mode` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'MODEL/TEMPLATE_FALLBACK',
  `model_id` bigint(20) DEFAULT NULL COMMENT '模型ID',
  `model_name` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '模型名称快照',
  `prompt_version` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Prompt版本',
  `input_tokens` int(11) DEFAULT NULL COMMENT '输入Token',
  `output_tokens` int(11) DEFAULT NULL COMMENT '输出Token',
  `estimated_cost` decimal(18,6) DEFAULT NULL COMMENT '估算成本',
  `analysis_flow_instance_id` bigint(20) DEFAULT NULL COMMENT '分析Flow实例ID',
  `execution_flow_instance_id` bigint(20) DEFAULT NULL COMMENT '执行Flow实例ID',
  `error_code` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '错误码',
  `error_message` varchar(1000) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '脱敏错误信息',
  `started_at` datetime DEFAULT NULL COMMENT '开始时间',
  `analysis_finished_at` datetime DEFAULT NULL COMMENT '分析完成时间',
  `finished_at` datetime DEFAULT NULL COMMENT '完成时间',
  `version` int(11) NOT NULL DEFAULT '0' COMMENT '乐观锁版本',
  `create_dept` bigint(20) DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) DEFAULT NULL COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` bigint(20) DEFAULT NULL COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `del_flag` char(1) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '0' COMMENT '删除标志',
  `attr1` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段1',
  `attr2` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段2',
  `attr3` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段3',
  `attr4` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段4',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_decision_tenant_scene_status` (`tenant_id`,`scene_code`,`status`) USING BTREE,
  KEY `idx_decision_biz` (`tenant_id`,`biz_type`,`biz_id`) USING BTREE,
  KEY `idx_decision_create_time` (`tenant_id`,`create_time`) USING BTREE,
  KEY `idx_decision_parent` (`parent_run_id`) USING BTREE,
  KEY `idx_decision_analysis_flow` (`analysis_flow_instance_id`) USING BTREE,
  KEY `idx_decision_execution_flow` (`execution_flow_instance_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='AI工业决策运行';







DROP TABLE IF EXISTS `ai_flow`;

CREATE TABLE `ai_flow` (
  `id` bigint(20) NOT NULL COMMENT '主键',
  `tenant_id` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT '000000' COMMENT '租户编号',
  `flow_name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '流程名称',
  `flow_key` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '流程标识(唯一, 定时/Webhook 引用)',
  `description` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '描述',
  `status` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'DRAFT' COMMENT '状态: DRAFT/PUBLISHED/OFFLINE',
  `version` int(11) NOT NULL DEFAULT '1' COMMENT '版本号(每次发布+1)',
  `config_json` longtext COLLATE utf8mb4_unicode_ci COMMENT '画布配置(JSON: nodes+edges)',
  `trigger_type` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT 'MANUAL' COMMENT '触发方式: MANUAL/SCHEDULE (逗号分隔可多选)',
  `cron_expr` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '定时 Cron 表达式',
  `max_retry` int(11) NOT NULL DEFAULT '1' COMMENT '节点失败最大重试次数',
  `create_dept` bigint(20) DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) DEFAULT NULL COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` bigint(20) DEFAULT NULL COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `del_flag` char(1) COLLATE utf8mb4_unicode_ci DEFAULT '0' COMMENT '删除标志（0代表存在 2代表删除）',
  `attr1` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段1',
  `attr2` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段2',
  `attr3` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段3',
  `attr4` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段4',
  `webhook_token` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Webhook访问令牌(空=不校验, flowKey本身即令牌)',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uk_flow_key` (`flow_key`) USING BTREE,
  KEY `idx_tenant_status` (`tenant_id`,`status`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='AI 流程定义';


DROP TABLE IF EXISTS `ai_flow_instance`;

CREATE TABLE `ai_flow_instance` (
  `id` bigint(20) NOT NULL COMMENT '主键',
  `tenant_id` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT '000000' COMMENT '租户编号',
  `flow_id` bigint(20) NOT NULL COMMENT '流程ID',
  `flow_version` int(11) NOT NULL DEFAULT '1' COMMENT '运行时的流程版本',
  `trigger_type` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'MANUAL' COMMENT '触发方式: MANUAL/SCHEDULE',
  `trigger_by` bigint(20) DEFAULT NULL COMMENT '触发人(定时任务=流程创建人, 用于SSE通知)',
  `input_json` longtext COLLATE utf8mb4_unicode_ci COMMENT '输入(JSON)',
  `output_json` longtext COLLATE utf8mb4_unicode_ci COMMENT '输出(JSON, 末节点输出)',
  `status` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'RUNNING' COMMENT '状态: RUNNING/SUCCEEDED/FAILED/STOPPED',
  `error_msg` varchar(2000) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '错误信息',
  `duration_ms` bigint(20) DEFAULT NULL COMMENT '总耗时(毫秒)',
  `node_total` int(11) DEFAULT '0' COMMENT '节点总数',
  `node_success` int(11) DEFAULT '0' COMMENT '成功节点数',
  `node_failed` int(11) DEFAULT '0' COMMENT '失败节点数',
  `start_time` datetime DEFAULT NULL COMMENT '开始时间',
  `end_time` datetime DEFAULT NULL COMMENT '结束时间',
  `create_dept` bigint(20) DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) DEFAULT NULL COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` bigint(20) DEFAULT NULL COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `del_flag` char(1) COLLATE utf8mb4_unicode_ci DEFAULT '0' COMMENT '删除标志（0代表存在 2代表删除）',
  `attr1` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段1',
  `attr2` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段2',
  `attr3` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段3',
  `attr4` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段4',
  `config_snapshot` longtext COLLATE utf8mb4_unicode_ci COMMENT '启动时画布配置快照(续跑用)',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_flow_id` (`flow_id`,`id`) USING BTREE,
  KEY `idx_status` (`status`) USING BTREE,
  KEY `idx_create_time` (`create_time`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='AI 流程运行实例';











DROP TABLE IF EXISTS `ai_flow_node_run`;

CREATE TABLE `ai_flow_node_run` (
  `id` bigint(20) NOT NULL COMMENT '主键',
  `tenant_id` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT '000000' COMMENT '租户编号',
  `instance_id` bigint(20) NOT NULL COMMENT '实例ID',
  `flow_id` bigint(20) NOT NULL COMMENT '流程ID(冗余, 便于查询)',
  `node_id` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '画布节点ID(如 node_1)',
  `node_name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '节点名称',
  `node_type` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '节点类型: LLM/AGENT/RAG/IF/CODE',
  `status` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '状态: PENDING/RUNNING/SUCCEEDED/FAILED/SKIPPED',
  `input_json` longtext COLLATE utf8mb4_unicode_ci COMMENT '输入(JSON, 渲染后的最终入参)',
  `output_json` longtext COLLATE utf8mb4_unicode_ci COMMENT '输出(JSON)',
  `error_msg` varchar(2000) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '错误信息',
  `retry_count` int(11) NOT NULL DEFAULT '0' COMMENT '已重试次数',
  `duration_ms` bigint(20) DEFAULT NULL COMMENT '耗时(毫秒)',
  `start_time` datetime DEFAULT NULL COMMENT '开始时间',
  `end_time` datetime DEFAULT NULL COMMENT '结束时间',
  `create_dept` bigint(20) DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) DEFAULT NULL COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` bigint(20) DEFAULT NULL COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `del_flag` char(1) COLLATE utf8mb4_unicode_ci DEFAULT '0' COMMENT '删除标志（0代表存在 2代表删除）',
  `attr1` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段1',
  `attr2` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段2',
  `attr3` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段3',
  `attr4` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段4',
  `batch_index` int(11) NOT NULL DEFAULT '0' COMMENT '循环批次索引(非循环执行=0)',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_instance_id` (`instance_id`) USING BTREE,
  KEY `idx_flow_id` (`flow_id`) USING BTREE,
  KEY `idx_instance_batch` (`instance_id`,`batch_index`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='AI 流程节点运行记录';























DROP TABLE IF EXISTS `ai_flow_version`;

CREATE TABLE `ai_flow_version` (
  `id` bigint(20) NOT NULL COMMENT '主键',
  `tenant_id` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT '000000' COMMENT '租户编号',
  `flow_id` bigint(20) NOT NULL COMMENT '流程ID',
  `flow_version` int(11) NOT NULL COMMENT '发布后的流程版本号',
  `flow_name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '流程名称(发布时快照)',
  `config_json` longtext COLLATE utf8mb4_unicode_ci COMMENT '画布配置快照(JSON: nodes+edges)',
  `description` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '发布说明',
  `create_dept` bigint(20) DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) DEFAULT NULL COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` bigint(20) DEFAULT NULL COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `del_flag` char(1) COLLATE utf8mb4_unicode_ci DEFAULT '0' COMMENT '删除标志（0代表存在 2代表删除）',
  `attr1` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段1',
  `attr2` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段2',
  `attr3` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段3',
  `attr4` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段4',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_flow_id_version` (`flow_id`,`flow_version`) USING BTREE,
  KEY `idx_create_time` (`create_time`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='AI 流程版本快照';


DROP TABLE IF EXISTS `ai_image_record`;

CREATE TABLE `ai_image_record` (
  `id` bigint(20) NOT NULL COMMENT '主键',
  `tenant_id` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT '000000' COMMENT '租户编号',
  `user_id` bigint(20) NOT NULL COMMENT '生成用户ID',
  `prompt` text COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '提示词',
  `image_url` varchar(500) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '图片URL（OSS）',
  `size` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT '1280*1280' COMMENT '尺寸',
  `model_id` bigint(20) DEFAULT NULL COMMENT '使用的模型ID',
  `model_name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '模型名称',
  `create_dept` bigint(20) DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) DEFAULT NULL COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` bigint(20) DEFAULT NULL COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `del_flag` char(1) COLLATE utf8mb4_unicode_ci DEFAULT '0' COMMENT '删除标志（0代表存在 2代表删除）',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_user_id` (`user_id`) USING BTREE,
  KEY `idx_create_time` (`create_time`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='AI 文生图记录';

DROP TABLE IF EXISTS `ai_kg_community`;

CREATE TABLE `ai_kg_community` (
  `id` bigint(20) NOT NULL COMMENT '主键',
  `tenant_id` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT '000000' COMMENT '租户编号',
  `graph_id` bigint(20) NOT NULL COMMENT '图谱ID',
  `community_level` int(11) DEFAULT '0' COMMENT '社区层级（v1 单层=0）',
  `parent_community_id` bigint(20) DEFAULT NULL COMMENT '父社区ID（v1 为空）',
  `community_index` int(11) DEFAULT NULL COMMENT '社区序号',
  `summary` text COLLATE utf8mb4_unicode_ci COMMENT '社区摘要（LLM 生成）',
  `summary_status` char(1) COLLATE utf8mb4_unicode_ci DEFAULT '0' COMMENT '摘要状态（0待生成 1生成中 2已完成 3失败）',
  `entity_count` int(11) DEFAULT '0' COMMENT '社区内实体数',
  `relation_count` int(11) DEFAULT '0' COMMENT '社区内关系数',
  `token_used` bigint(20) DEFAULT '0' COMMENT '摘要消耗token',
  `error_message` varchar(1024) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '错误信息',
  `create_dept` bigint(20) DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) DEFAULT NULL COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` bigint(20) DEFAULT NULL COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `del_flag` char(1) COLLATE utf8mb4_unicode_ci DEFAULT '0' COMMENT '删除标志（0代表存在 2代表删除）',
  `attr1` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段1',
  `attr2` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段2',
  `attr3` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段3',
  `attr4` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段4',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_graph_id` (`graph_id`) USING BTREE,
  KEY `idx_community_level` (`community_level`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='AI 知识图谱社区';


DROP TABLE IF EXISTS `ai_kg_entity`;

CREATE TABLE `ai_kg_entity` (
  `id` bigint(20) NOT NULL COMMENT '主键',
  `tenant_id` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT '000000' COMMENT '租户编号',
  `graph_id` bigint(20) NOT NULL COMMENT '图谱ID',
  `entity_name` varchar(256) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '实体名称',
  `entity_type` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '实体类型',
  `description` varchar(1024) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '实体描述',
  `confidence` decimal(3,2) DEFAULT NULL COMMENT '置信度（0-1）',
  `source_chunk_id` bigint(20) DEFAULT NULL COMMENT '来源切片ID',
  `mention_count` int(11) DEFAULT '1' COMMENT '被提及次数（同名合并）',
  `community_id` bigint(20) DEFAULT NULL COMMENT '所属社区ID',
  `create_dept` bigint(20) DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) DEFAULT NULL COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` bigint(20) DEFAULT NULL COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `del_flag` char(1) COLLATE utf8mb4_unicode_ci DEFAULT '0' COMMENT '删除标志（0代表存在 2代表删除）',
  `attr1` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段1',
  `attr2` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段2',
  `attr3` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段3',
  `attr4` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段4',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_graph_id` (`graph_id`) USING BTREE,
  KEY `idx_entity_name` (`entity_name`) USING BTREE,
  KEY `idx_entity_type` (`entity_type`) USING BTREE,
  KEY `idx_source_chunk` (`source_chunk_id`) USING BTREE,
  KEY `idx_community` (`community_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='AI 知识图谱实体';


DROP TABLE IF EXISTS `ai_kg_relation`;

CREATE TABLE `ai_kg_relation` (
  `id` bigint(20) NOT NULL COMMENT '主键',
  `tenant_id` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT '000000' COMMENT '租户编号',
  `graph_id` bigint(20) NOT NULL COMMENT '图谱ID',
  `source_entity_id` bigint(20) NOT NULL COMMENT '头实体ID',
  `target_entity_id` bigint(20) NOT NULL COMMENT '尾实体ID',
  `relation_type` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '关系类型',
  `description` varchar(1024) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '关系描述',
  `strength` int(11) DEFAULT NULL COMMENT '关系强度（0-10）',
  `confidence` decimal(3,2) DEFAULT NULL COMMENT '置信度（0-1）',
  `source_chunk_id` bigint(20) DEFAULT NULL COMMENT '来源切片ID',
  `create_dept` bigint(20) DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) DEFAULT NULL COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` bigint(20) DEFAULT NULL COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `del_flag` char(1) COLLATE utf8mb4_unicode_ci DEFAULT '0' COMMENT '删除标志（0代表存在 2代表删除）',
  `attr1` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段1',
  `attr2` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段2',
  `attr3` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段3',
  `attr4` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段4',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_graph_id` (`graph_id`) USING BTREE,
  KEY `idx_source` (`source_entity_id`) USING BTREE,
  KEY `idx_target` (`target_entity_id`) USING BTREE,
  KEY `idx_source_chunk` (`source_chunk_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='AI 知识图谱关系';


DROP TABLE IF EXISTS `ai_knowledge`;

CREATE TABLE `ai_knowledge` (
  `id` bigint(20) NOT NULL COMMENT '主键',
  `tenant_id` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT '000000' COMMENT '租户编号',
  `knowledge_name` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '知识库名称',
  `description` varchar(512) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '描述',
  `embedding_model` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '使用的 Embedding 模型',
  `vector_store` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT 'milvus' COMMENT '向量存储类型',
  `vector_index_status` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'READY' COMMENT '向量索引状态',
  `vector_index_progress` tinyint(3) unsigned NOT NULL DEFAULT '0' COMMENT '向量索引重建进度 0-100',
  `vector_index_error` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '向量索引错误信息',
  `vector_index_updated_time` datetime DEFAULT NULL COMMENT '向量索引最近完成时间',
  `status` char(1) COLLATE utf8mb4_unicode_ci DEFAULT '1' COMMENT '状态（1正常 0停用）',
  `separator` varchar(16) COLLATE utf8mb4_unicode_ci DEFAULT '#' COMMENT '知识分隔符',
  `overlap_char` int(11) DEFAULT '30' COMMENT '重叠字符数',
  `text_block_size` int(11) DEFAULT '500' COMMENT '文本块大小',
  `retrieve_limit` int(11) DEFAULT '5' COMMENT '检索条数',
  `similarity_threshold` double DEFAULT '0.5' COMMENT '相似度阈值',
  `enable_rerank` tinyint(1) DEFAULT '0' COMMENT '是否启用重排序（0否 1是）',
  `rerank_model` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '重排序模型名称',
  `enable_hybrid` tinyint(1) DEFAULT '0' COMMENT '是否启用混合检索（0否 1是）',
  `hybrid_alpha` double DEFAULT '0.5' COMMENT '混合检索权重（0=纯向量 1=纯关键词）',
  `system_prompt` varchar(1024) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '系统提示词',
  `create_dept` bigint(20) DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) DEFAULT NULL COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` bigint(20) DEFAULT NULL COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `del_flag` char(1) COLLATE utf8mb4_unicode_ci DEFAULT '0' COMMENT '删除标志（0代表存在 2代表删除）',
  `attr1` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段1',
  `attr2` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段2',
  `attr3` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段3',
  `attr4` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段4',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='AI 知识库';


DROP TABLE IF EXISTS `ai_knowledge_chunk`;

CREATE TABLE `ai_knowledge_chunk` (
  `id` bigint(20) NOT NULL COMMENT '主键',
  `tenant_id` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT '000000' COMMENT '租户编号',
  `document_id` bigint(20) NOT NULL COMMENT '文档ID',
  `knowledge_id` bigint(20) NOT NULL COMMENT '知识库ID',
  `content` text COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '片段内容',
  `chunk_index` int(11) DEFAULT NULL COMMENT '片段序号',
  `vector_id` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '向量数据库中的ID',
  `extraction_status` char(1) COLLATE utf8mb4_unicode_ci DEFAULT '0' COMMENT '图谱抽取状态（0待处理 1处理中 2已完成 3失败）',
  `entity_count` int(11) DEFAULT '0' COMMENT '抽取实体数',
  `relation_count` int(11) DEFAULT '0' COMMENT '抽取关系数',
  `token_used` bigint(20) DEFAULT '0' COMMENT '抽取消耗token',
  `kg_error_message` varchar(1024) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '抽取错误信息',
  `create_dept` bigint(20) DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) DEFAULT NULL COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` bigint(20) DEFAULT NULL COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `del_flag` char(1) COLLATE utf8mb4_unicode_ci DEFAULT '0' COMMENT '删除标志（0代表存在 2代表删除）',
  `attr1` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段1',
  `attr2` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段2',
  `attr3` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段3',
  `attr4` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段4',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_knowledge_id` (`knowledge_id`) USING BTREE,
  KEY `idx_document_id` (`document_id`) USING BTREE,
  FULLTEXT KEY `ft_content` (`content`) /*!50100 WITH PARSER `ngram` */ 
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='AI 知识库文档切片';


DROP TABLE IF EXISTS `ai_knowledge_document`;

CREATE TABLE `ai_knowledge_document` (
  `id` bigint(20) NOT NULL COMMENT '主键',
  `tenant_id` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT '000000' COMMENT '租户编号',
  `knowledge_id` bigint(20) NOT NULL COMMENT '知识库ID',
  `file_name` varchar(256) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '文件名',
  `file_path` varchar(512) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'OSS 文件路径',
  `file_size` bigint(20) DEFAULT NULL COMMENT '文件大小（字节）',
  `chunk_count` int(11) DEFAULT '0' COMMENT '分段数量',
  `status` char(1) COLLATE utf8mb4_unicode_ci DEFAULT '0' COMMENT '状态（0待解析 1解析中 2已完成 3失败）',
  `error_message` varchar(512) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '错误信息',
  `create_dept` bigint(20) DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) DEFAULT NULL COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` bigint(20) DEFAULT NULL COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `del_flag` char(1) COLLATE utf8mb4_unicode_ci DEFAULT '0' COMMENT '删除标志（0代表存在 2代表删除）',
  `attr1` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段1',
  `attr2` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段2',
  `attr3` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段3',
  `attr4` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段4',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_knowledge_id` (`knowledge_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='AI 知识库文档';


DROP TABLE IF EXISTS `ai_knowledge_graph`;

CREATE TABLE `ai_knowledge_graph` (
  `id` bigint(20) NOT NULL COMMENT '主键',
  `tenant_id` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT '000000' COMMENT '租户编号',
  `knowledge_id` bigint(20) NOT NULL COMMENT '知识库ID',
  `graph_name` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '图谱名称',
  `graph_status` char(1) COLLATE utf8mb4_unicode_ci DEFAULT '0' COMMENT '状态（0未构建 1构建中 2已完成 3失败）',
  `node_count` int(11) DEFAULT '0' COMMENT '实体节点数',
  `relationship_count` int(11) DEFAULT '0' COMMENT '关系数',
  `community_count` int(11) DEFAULT '0' COMMENT '社区数',
  `model_id` bigint(20) DEFAULT NULL COMMENT '抽取用的LLM模型ID',
  `entity_types` varchar(512) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '实体类型（逗号分隔）',
  `relation_types` varchar(512) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '关系类型（逗号分隔）',
  `config` text COLLATE utf8mb4_unicode_ci COMMENT '图谱配置（JSON）',
  `error_message` varchar(1024) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '错误信息',
  `create_dept` bigint(20) DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) DEFAULT NULL COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` bigint(20) DEFAULT NULL COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `del_flag` char(1) COLLATE utf8mb4_unicode_ci DEFAULT '0' COMMENT '删除标志（0代表存在 2代表删除）',
  `attr1` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段1',
  `attr2` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段2',
  `attr3` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段3',
  `attr4` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段4',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_knowledge_id` (`knowledge_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='AI 知识图谱实例';


DROP TABLE IF EXISTS `ai_mcp_market`;

CREATE TABLE `ai_mcp_market` (
  `id` bigint(20) NOT NULL COMMENT '主键',
  `tenant_id` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT '000000' COMMENT '租户编号',
  `name` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '市场名称',
  `url` varchar(500) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '市场URL（返回工具列表JSON）',
  `description` varchar(512) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '描述',
  `auth_config` text COLLATE utf8mb4_unicode_ci COMMENT '认证配置（JSON）',
  `status` char(1) COLLATE utf8mb4_unicode_ci DEFAULT '1' COMMENT '状态（1启用 0停用）',
  `create_dept` bigint(20) DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) DEFAULT NULL COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` bigint(20) DEFAULT NULL COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `del_flag` char(1) COLLATE utf8mb4_unicode_ci DEFAULT '0' COMMENT '删除标志（0代表存在 2代表删除）',
  `attr1` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段1',
  `attr2` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段2',
  `attr3` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段3',
  `attr4` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段4',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='AI MCP 市场源';


DROP TABLE IF EXISTS `ai_mcp_market_tool`;

CREATE TABLE `ai_mcp_market_tool` (
  `id` bigint(20) NOT NULL COMMENT '主键',
  `tenant_id` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT '000000' COMMENT '租户编号',
  `market_id` bigint(20) NOT NULL COMMENT '市场ID',
  `tool_name` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '工具名称',
  `tool_description` text COLLATE utf8mb4_unicode_ci COMMENT '工具描述',
  `tool_version` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '工具版本',
  `tool_metadata` text COLLATE utf8mb4_unicode_ci COMMENT '工具元数据JSON（含 command/args/baseUrl 等）',
  `is_loaded` char(1) COLLATE utf8mb4_unicode_ci DEFAULT '0' COMMENT '是否已加载到本地ai_tool（1是 0否）',
  `local_tool_id` bigint(20) DEFAULT NULL COMMENT '关联 ai_tool.id',
  `create_dept` bigint(20) DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) DEFAULT NULL COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` bigint(20) DEFAULT NULL COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `del_flag` char(1) COLLATE utf8mb4_unicode_ci DEFAULT '0' COMMENT '删除标志（0代表存在 2代表删除）',
  `attr1` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段1',
  `attr2` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段2',
  `attr3` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段3',
  `attr4` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段4',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_market_id` (`market_id`) USING BTREE,
  KEY `idx_tool_name` (`tool_name`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='AI MCP 市场工具';


DROP TABLE IF EXISTS `ai_message`;

CREATE TABLE `ai_message` (
  `id` bigint(20) NOT NULL COMMENT '主键',
  `tenant_id` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT '000000' COMMENT '租户编号',
  `session_id` bigint(20) NOT NULL COMMENT '会话ID',
  `role` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '角色: USER/ASSISTANT/SYSTEM',
  `content` text COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '消息内容',
  `token_usage` bigint(20) DEFAULT NULL COMMENT 'Token 消耗',
  `feedback` varchar(16) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '用户反馈: LIKE/DISLIKE',
  `feedback_content` varchar(512) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '反馈内容',
  `create_dept` bigint(20) DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) DEFAULT NULL COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` bigint(20) DEFAULT NULL COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `del_flag` char(1) COLLATE utf8mb4_unicode_ci DEFAULT '0' COMMENT '删除标志（0代表存在 2代表删除）',
  `attr1` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段1',
  `attr2` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段2',
  `attr3` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段3',
  `attr4` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段4',
  `model_id` bigint(20) DEFAULT NULL COMMENT '使用的模型ID',
  `input_tokens` int(11) DEFAULT NULL COMMENT '输入 Token 数',
  `output_tokens` int(11) DEFAULT NULL COMMENT '输出 Token 数',
  `thinking_content` mediumtext COLLATE utf8mb4_unicode_ci COMMENT '推理过程内容（enableThinking 时存）',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_session_id` (`session_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='AI 对话消息';


DROP TABLE IF EXISTS `ai_model`;

CREATE TABLE `ai_model` (
  `id` bigint(20) NOT NULL COMMENT '主键',
  `tenant_id` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT '000000' COMMENT '租户编号',
  `provider_id` bigint(20) NOT NULL COMMENT '关联厂商ID',
  `model_name` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '模型名称（如 deepseek-chat）',
  `display_name` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '显示名称',
  `model_type` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '类型: CHAT/EMBEDDING/RERANK',
  `context_window` int(11) DEFAULT NULL COMMENT '上下文窗口',
  `input_capabilities` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'TEXT' COMMENT '输入能力，逗号分隔',
  `output_capabilities` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'TEXT' COMMENT '输出能力，逗号分隔',
  `api_protocol` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '调用协议',
  `embedding_dimension` int(11) DEFAULT NULL COMMENT '向量维度，仅 EMBEDDING 使用',
  `max_tokens` int(11) DEFAULT '4096' COMMENT '最大输出 Token',
  `temperature` decimal(3,2) DEFAULT '0.70' COMMENT '温度参数',
  `is_default` char(1) COLLATE utf8mb4_unicode_ci DEFAULT '0' COMMENT '是否默认模型（1是 0否）',
  `status` char(1) COLLATE utf8mb4_unicode_ci DEFAULT '1' COMMENT '状态（1正常 0停用）',
  `create_dept` bigint(20) DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) DEFAULT NULL COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` bigint(20) DEFAULT NULL COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `del_flag` char(1) COLLATE utf8mb4_unicode_ci DEFAULT '0' COMMENT '删除标志（0代表存在 2代表删除）',
  `attr1` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段1',
  `attr2` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段2',
  `attr3` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段3',
  `attr4` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段4',
  `input_price_per_million` decimal(10,6) DEFAULT NULL COMMENT '输入价格（元/百万Token）',
  `output_price_per_million` decimal(10,6) DEFAULT NULL COMMENT '输出价格（元/百万Token）',
  `currency` varchar(16) COLLATE utf8mb4_unicode_ci DEFAULT 'CNY' COMMENT '币种：CNY/USD',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_provider_id` (`provider_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='AI 模型配置';


DROP TABLE IF EXISTS `ai_prompt_template`;

CREATE TABLE `ai_prompt_template` (
  `id` bigint(20) NOT NULL COMMENT '主键',
  `tenant_id` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT '000000' COMMENT '租户ID',
  `template_name` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '模板名称',
  `template_key` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '模板标识（如 erp_query_agent/erp_report_agent/supervisor）',
  `content` text COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '模板内容（支持 {{variable}} 占位符）',
  `description` varchar(512) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '描述',
  `is_default` char(1) COLLATE utf8mb4_unicode_ci DEFAULT '0' COMMENT '是否默认模板（1是 0否）',
  `version` int(11) DEFAULT '1' COMMENT '版本号',
  `status` char(1) COLLATE utf8mb4_unicode_ci DEFAULT '1' COMMENT '状态（1正常 0停用）',
  `create_dept` bigint(20) DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) DEFAULT NULL COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` bigint(20) DEFAULT NULL COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `del_flag` char(1) COLLATE utf8mb4_unicode_ci DEFAULT '0' COMMENT '删除标志（0代表存在 2代表删除）',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uk_template_key` (`template_key`,`tenant_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='AI Prompt 模板';


DROP TABLE IF EXISTS `ai_provider`;

CREATE TABLE `ai_provider` (
  `id` bigint(20) NOT NULL COMMENT '主键',
  `tenant_id` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT '000000' COMMENT '租户编号',
  `name` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '厂商名称',
  `api_host` varchar(256) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'API 地址',
  `api_key` varchar(512) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'API Key（Jasypt 加密存储）',
  `provider_type` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '厂商类型: OPENAI/DASHSCOPE/ZHIPU/OLLAMA',
  `status` char(1) COLLATE utf8mb4_unicode_ci DEFAULT '1' COMMENT '状态（1正常 0停用）',
  `create_dept` bigint(20) DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) DEFAULT NULL COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` bigint(20) DEFAULT NULL COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `del_flag` char(1) COLLATE utf8mb4_unicode_ci DEFAULT '0' COMMENT '删除标志（0代表存在 2代表删除）',
  `attr1` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段1',
  `attr2` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段2',
  `attr3` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段3',
  `attr4` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段4',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='AI 厂商配置';


DROP TABLE IF EXISTS `ai_session`;

CREATE TABLE `ai_session` (
  `id` bigint(20) NOT NULL COMMENT '主键',
  `tenant_id` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT '000000' COMMENT '租户编号',
  `user_id` bigint(20) NOT NULL COMMENT '用户ID',
  `title` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '会话标题',
  `model_name` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '使用的模型名称',
  `create_dept` bigint(20) DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) DEFAULT NULL COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` bigint(20) DEFAULT NULL COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `del_flag` char(1) COLLATE utf8mb4_unicode_ci DEFAULT '0' COMMENT '删除标志（0代表存在 2代表删除）',
  `attr1` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段1',
  `attr2` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段2',
  `attr3` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段3',
  `attr4` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段4',
  `enabled_tool_ids` varchar(1024) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '会话启用的工具ID列表（逗号分隔，null=全部）',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_user_id` (`user_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='AI 对话会话';


DROP TABLE IF EXISTS `ai_sql_example`;

CREATE TABLE `ai_sql_example` (
  `id` bigint(20) NOT NULL COMMENT '主键',
  `tenant_id` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT '000000' COMMENT '租户ID',
  `question` varchar(512) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '用户问题（自然语言）',
  `sql_template` text COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'SQL 模板（可含 {{variable}} 占位符）',
  `category` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '业务分类：INVENTORY/SALES/PURCHASE/PRODUCTION/GENERAL',
  `description` varchar(512) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '描述',
  `sort_order` int(11) DEFAULT '0' COMMENT '排序号',
  `status` char(1) COLLATE utf8mb4_unicode_ci DEFAULT '1' COMMENT '状态（1正常 0停用）',
  `create_dept` bigint(20) DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) DEFAULT NULL COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` bigint(20) DEFAULT NULL COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `del_flag` char(1) COLLATE utf8mb4_unicode_ci DEFAULT '0' COMMENT '删除标志（0代表存在 2代表删除）',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_category` (`category`) USING BTREE,
  KEY `idx_status` (`status`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='AI SQL Few-Shot 示例';


DROP TABLE IF EXISTS `ai_token_usage`;

CREATE TABLE `ai_token_usage` (
  `id` bigint(20) NOT NULL COMMENT '主键',
  `tenant_id` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT '000000' COMMENT '租户ID',
  `user_id` bigint(20) NOT NULL COMMENT '用户ID',
  `user_name` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '用户名称（冗余，避免关联查询）',
  `model_id` bigint(20) NOT NULL COMMENT '模型ID',
  `model_name` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '模型名称（冗余）',
  `usage_date` date NOT NULL COMMENT '统计日期',
  `total_input_tokens` bigint(20) DEFAULT '0' COMMENT '当日输入 Token 总量',
  `total_output_tokens` bigint(20) DEFAULT '0' COMMENT '当日输出 Token 总量',
  `total_tokens` bigint(20) DEFAULT '0' COMMENT '当日 Token 总量（input+output）',
  `request_count` int(11) DEFAULT '0' COMMENT '当日请求次数',
  `total_cost` decimal(12,4) DEFAULT '0.0000' COMMENT '当日总成本（元）',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uk_user_model_date` (`tenant_id`,`user_id`,`model_id`,`usage_date`) USING BTREE,
  KEY `idx_user_date` (`tenant_id`,`user_id`,`usage_date`) USING BTREE,
  KEY `idx_model_date` (`tenant_id`,`model_id`,`usage_date`) USING BTREE,
  KEY `idx_date` (`usage_date`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='AI Token 用量日统计';


DROP TABLE IF EXISTS `ai_tool`;

CREATE TABLE `ai_tool` (
  `id` bigint(20) NOT NULL COMMENT '主键',
  `tenant_id` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT '000000' COMMENT '租户编号',
  `tool_name` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '工具名称（唯一标识，snake_case）',
  `display_name` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '显示名称',
  `description` varchar(512) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '工具描述（AI 理解用途）',
  `tool_type` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '类型: BUILTIN/LOCAL/REMOTE',
  `config_json` text COLLATE utf8mb4_unicode_ci COMMENT '工具配置（JSON 格式，LOCAL/REMOTE 类型使用）',
  `status` varchar(16) COLLATE utf8mb4_unicode_ci DEFAULT '1' COMMENT '状态: 0启用/1停用，默认停用',
  `create_dept` bigint(20) DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) DEFAULT NULL COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` bigint(20) DEFAULT NULL COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `del_flag` char(1) COLLATE utf8mb4_unicode_ci DEFAULT '0' COMMENT '删除标志（0代表存在 2代表删除）',
  `attr1` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段1',
  `attr2` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段2',
  `attr3` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段3',
  `attr4` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段4',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uk_tenant_tool_name` (`tenant_id`,`tool_name`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='AI 工具配置';


DROP TABLE IF EXISTS `app_user_agreement`;

CREATE TABLE `app_user_agreement` (
  `id` bigint(20) NOT NULL COMMENT '主键(雪花ID,ASSIGN_ID非自增)',
  `tenant_id` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT '000000' COMMENT '租户ID',
  `user_id` bigint(20) NOT NULL COMMENT '用户ID',
  `agreement_key` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '协议标识(privacy_policy/user_service_agreement)',
  `agreement_version` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '协议版本',
  `agree_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '同意时间',
  `remark` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `create_dept` bigint(20) DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) DEFAULT NULL COMMENT '创建人',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_by` bigint(20) DEFAULT NULL COMMENT '更新人',
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `del_flag` char(1) COLLATE utf8mb4_unicode_ci DEFAULT '0' COMMENT '删除标志',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uk_user_agreement` (`user_id`,`agreement_key`,`tenant_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='App用户协议同意记录';


DROP TABLE IF EXISTS `es_seal`;

CREATE TABLE `es_seal` (
  `seal_id` bigint(20) NOT NULL COMMENT '印章ID',
  `tenant_id` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '租户ID',
  `seal_type` char(1) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '印章类型(1个人章 2公司章)',
  `seal_name` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '印章名称',
  `owner_user_id` bigint(20) DEFAULT NULL COMMENT '个人章归属用户ID(公司章为NULL)',
  `seal_oss_id` bigint(20) NOT NULL COMMENT '印章原图OSS ID(私有桶,仅服务端使用)',
  `preview_oss_id` bigint(20) DEFAULT NULL COMMENT '预览图OSS ID(低清+水印,前端可见)',
  `img_width` int(11) NOT NULL COMMENT '印章原图宽(px)',
  `img_height` int(11) NOT NULL COMMENT '印章原图高(px)',
  `status` char(1) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '0' COMMENT '状态(0草稿 1启用 2停用 3销毁)',
  `seal_version` int(11) NOT NULL DEFAULT '1' COMMENT '印章版本(更换章面自增)',
  `valid_from` date DEFAULT NULL COMMENT '生效日期',
  `valid_to` date DEFAULT NULL COMMENT '失效日期',
  `remark` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `create_dept` bigint(20) DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) DEFAULT NULL COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` bigint(20) DEFAULT NULL COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `del_flag` char(1) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '0' COMMENT '删除标志(0存在 1删除)',
  PRIMARY KEY (`seal_id`) USING BTREE,
  KEY `idx_es_seal_tenant_type` (`tenant_id`,`seal_type`) USING BTREE,
  KEY `idx_es_seal_owner` (`owner_user_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='电子印章';


DROP TABLE IF EXISTS `es_seal_grant`;

CREATE TABLE `es_seal_grant` (
  `grant_id` bigint(20) NOT NULL COMMENT '授权ID',
  `tenant_id` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '租户ID',
  `seal_id` bigint(20) NOT NULL COMMENT '印章ID',
  `grantee_user_id` bigint(20) DEFAULT NULL COMMENT '被授权用户ID(用户级授权)',
  `grantee_dept_id` bigint(20) DEFAULT NULL COMMENT '被授权部门ID(部门级授权)',
  `biz_type` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '限定业务场景(NULL=不限)',
  `can_sign_alone` char(1) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '0' COMMENT '可否单独用章(0否 1是)',
  `valid_from` datetime DEFAULT NULL COMMENT '授权生效时间',
  `valid_to` datetime DEFAULT NULL COMMENT '授权失效时间',
  `status` char(1) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '1' COMMENT '状态(0停用 1启用)',
  `grant_by` bigint(20) DEFAULT NULL COMMENT '授权人用户ID',
  `remark` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `create_dept` bigint(20) DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) DEFAULT NULL COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` bigint(20) DEFAULT NULL COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `del_flag` char(1) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '0' COMMENT '删除标志(0存在 1删除)',
  PRIMARY KEY (`grant_id`) USING BTREE,
  KEY `idx_es_grant_seal` (`seal_id`,`status`) USING BTREE,
  KEY `idx_es_grant_user` (`grantee_user_id`,`status`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='印章使用授权';

DROP TABLE IF EXISTS `es_signature`;

CREATE TABLE `es_signature` (
  `signature_id` bigint(20) NOT NULL COMMENT '签名ID',
  `tenant_id` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '租户ID',
  `biz_type` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '业务类型',
  `biz_id` bigint(20) DEFAULT NULL COMMENT '业务单据ID',
  `biz_no` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '业务单据编号(冗余快照)',
  `signer_user_id` bigint(20) NOT NULL COMMENT '签署人用户ID',
  `signer_name` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '签署人姓名(冗余快照)',
  `signer_dept_id` bigint(20) DEFAULT NULL COMMENT '签署人部门ID(快照)',
  `seal_id` bigint(20) DEFAULT NULL COMMENT '所用印章ID(逻辑签名可空)',
  `seal_type` char(1) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '印章类型快照(1个人 2公司)',
  `signature_meaning` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '签署含义',
  `auth_method` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '认证方式(PASSWORD/SMS/FACE/LOGIN_ONLY)',
  `src_doc_oss_id` bigint(20) DEFAULT NULL COMMENT '签署前文档OSS ID',
  `src_doc_hash` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '签署前文档SM3',
  `doc_oss_id` bigint(20) DEFAULT NULL COMMENT '签署后文档OSS ID',
  `doc_hash` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '签署后文档SM3',
  `doc_id` bigint(20) DEFAULT NULL COMMENT '关联 es_sign_document.doc_id',
  `signed_at` datetime NOT NULL COMMENT '签署时间(服务端时间)',
  `sign_ip` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '签署IP',
  `sign_ua` varchar(512) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '签署User-Agent',
  `prev_hash` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '前一条链哈希(链首为NULL)',
  `chain_hash` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '本条链哈希(SM3)',
  `remark` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`signature_id`) USING BTREE,
  KEY `idx_es_sig_biz` (`tenant_id`,`biz_type`,`biz_id`) USING BTREE,
  KEY `idx_es_sig_signer` (`signer_user_id`,`signed_at`) USING BTREE,
  KEY `idx_es_sig_chain` (`tenant_id`,`signature_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='电子签名记录(append-only,无更新/删除字段)';


DROP TABLE IF EXISTS `es_sign_document`;

CREATE TABLE `es_sign_document` (
  `doc_id` bigint(20) NOT NULL COMMENT '文档ID',
  `tenant_id` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '租户ID',
  `biz_type` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '业务类型',
  `biz_id` bigint(20) NOT NULL COMMENT '业务单据ID',
  `file_oss_id` bigint(20) NOT NULL COMMENT '正文文件OSS ID(仅PDF)',
  `file_name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '原始文件名',
  `file_size` bigint(20) DEFAULT NULL COMMENT '文件大小(字节)',
  `file_hash` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '上传时SM3值(验签比对基准)',
  `page_count` int(11) DEFAULT NULL COMMENT 'PDF页数',
  `doc_version` int(11) NOT NULL DEFAULT '1' COMMENT '正文版本',
  `is_current` char(1) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '1' COMMENT '是否当前生效版本(1是 0否)',
  `signed_oss_id` bigint(20) DEFAULT NULL COMMENT '签章后文件OSS ID',
  `sign_status` char(1) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '0' COMMENT '签署状态(0未签 1部分签 2已签)',
  `create_dept` bigint(20) DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) DEFAULT NULL COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` bigint(20) DEFAULT NULL COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `del_flag` char(1) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '0' COMMENT '删除标志(0存在 1删除)',
  PRIMARY KEY (`doc_id`) USING BTREE,
  KEY `idx_es_doc_biz` (`tenant_id`,`biz_type`,`biz_id`,`is_current`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='待签文档正文';


DROP TABLE IF EXISTS `flw_channel_definition`;

CREATE TABLE `flw_channel_definition` (
  `ID_` varchar(255) NOT NULL,
  `NAME_` varchar(255) DEFAULT NULL,
  `VERSION_` int(11) DEFAULT NULL,
  `KEY_` varchar(255) DEFAULT NULL,
  `CATEGORY_` varchar(255) DEFAULT NULL,
  `DEPLOYMENT_ID_` varchar(255) DEFAULT NULL,
  `CREATE_TIME_` datetime(3) DEFAULT NULL,
  `TENANT_ID_` varchar(255) DEFAULT NULL,
  `RESOURCE_NAME_` varchar(255) DEFAULT NULL,
  `DESCRIPTION_` varchar(255) DEFAULT NULL,
  `TYPE_` varchar(255) DEFAULT NULL,
  `IMPLEMENTATION_` varchar(255) DEFAULT NULL,
  PRIMARY KEY (`ID_`) USING BTREE,
  UNIQUE KEY `ACT_IDX_CHANNEL_DEF_UNIQ` (`KEY_`,`VERSION_`,`TENANT_ID_`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8 ROW_FORMAT=DYNAMIC;

DROP TABLE IF EXISTS `flw_event_definition`;

CREATE TABLE `flw_event_definition` (
  `ID_` varchar(255) NOT NULL,
  `NAME_` varchar(255) DEFAULT NULL,
  `VERSION_` int(11) DEFAULT NULL,
  `KEY_` varchar(255) DEFAULT NULL,
  `CATEGORY_` varchar(255) DEFAULT NULL,
  `DEPLOYMENT_ID_` varchar(255) DEFAULT NULL,
  `TENANT_ID_` varchar(255) DEFAULT NULL,
  `RESOURCE_NAME_` varchar(255) DEFAULT NULL,
  `DESCRIPTION_` varchar(255) DEFAULT NULL,
  PRIMARY KEY (`ID_`) USING BTREE,
  UNIQUE KEY `ACT_IDX_EVENT_DEF_UNIQ` (`KEY_`,`VERSION_`,`TENANT_ID_`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8 ROW_FORMAT=DYNAMIC;

DROP TABLE IF EXISTS `flw_event_deployment`;

CREATE TABLE `flw_event_deployment` (
  `ID_` varchar(255) NOT NULL,
  `NAME_` varchar(255) DEFAULT NULL,
  `CATEGORY_` varchar(255) DEFAULT NULL,
  `DEPLOY_TIME_` datetime(3) DEFAULT NULL,
  `TENANT_ID_` varchar(255) DEFAULT NULL,
  `PARENT_DEPLOYMENT_ID_` varchar(255) DEFAULT NULL,
  PRIMARY KEY (`ID_`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8 ROW_FORMAT=DYNAMIC;

DROP TABLE IF EXISTS `flw_event_resource`;

CREATE TABLE `flw_event_resource` (
  `ID_` varchar(255) NOT NULL,
  `NAME_` varchar(255) DEFAULT NULL,
  `DEPLOYMENT_ID_` varchar(255) DEFAULT NULL,
  `RESOURCE_BYTES_` longblob,
  PRIMARY KEY (`ID_`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8 ROW_FORMAT=DYNAMIC;

DROP TABLE IF EXISTS `flw_ev_databasechangelog`;

CREATE TABLE `flw_ev_databasechangelog` (
  `ID` varchar(255) NOT NULL,
  `AUTHOR` varchar(255) NOT NULL,
  `FILENAME` varchar(255) NOT NULL,
  `DATEEXECUTED` datetime DEFAULT NULL,
  `ORDEREXECUTED` int(11) NOT NULL,
  `EXECTYPE` varchar(10) NOT NULL,
  `MD5SUM` varchar(35) DEFAULT NULL,
  `DESCRIPTION` varchar(255) DEFAULT NULL,
  `COMMENTS` varchar(255) DEFAULT NULL,
  `TAG` varchar(255) DEFAULT NULL,
  `LIQUIBASE` varchar(20) DEFAULT NULL,
  `CONTEXTS` varchar(255) DEFAULT NULL,
  `LABELS` varchar(255) DEFAULT NULL,
  `DEPLOYMENT_ID` varchar(10) DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8 ROW_FORMAT=DYNAMIC;


DROP TABLE IF EXISTS `flw_ev_databasechangeloglock`;

CREATE TABLE `flw_ev_databasechangeloglock` (
  `ID` int(11) NOT NULL,
  `LOCKED` tinyint(4) NOT NULL,
  `LOCKGRANTED` datetime DEFAULT NULL,
  `LOCKEDBY` varchar(255) DEFAULT NULL,
  PRIMARY KEY (`ID`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8 ROW_FORMAT=DYNAMIC;


DROP TABLE IF EXISTS `flw_ru_batch`;

CREATE TABLE `flw_ru_batch` (
  `ID_` varchar(64) COLLATE utf8_bin NOT NULL,
  `REV_` int(11) DEFAULT NULL,
  `TYPE_` varchar(64) COLLATE utf8_bin NOT NULL,
  `SEARCH_KEY_` varchar(255) COLLATE utf8_bin DEFAULT NULL,
  `SEARCH_KEY2_` varchar(255) COLLATE utf8_bin DEFAULT NULL,
  `CREATE_TIME_` datetime(3) DEFAULT NULL,
  `COMPLETE_TIME_` datetime(3) DEFAULT NULL,
  `STATUS_` varchar(255) COLLATE utf8_bin DEFAULT NULL,
  `BATCH_DOC_ID_` varchar(64) COLLATE utf8_bin DEFAULT NULL,
  `TENANT_ID_` varchar(255) COLLATE utf8_bin DEFAULT '',
  PRIMARY KEY (`ID_`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_bin ROW_FORMAT=DYNAMIC;

DROP TABLE IF EXISTS `flw_ru_batch_part`;

CREATE TABLE `flw_ru_batch_part` (
  `ID_` varchar(64) COLLATE utf8_bin NOT NULL,
  `REV_` int(11) DEFAULT NULL,
  `BATCH_ID_` varchar(64) COLLATE utf8_bin DEFAULT NULL,
  `TYPE_` varchar(64) COLLATE utf8_bin NOT NULL,
  `SCOPE_ID_` varchar(64) COLLATE utf8_bin DEFAULT NULL,
  `SUB_SCOPE_ID_` varchar(64) COLLATE utf8_bin DEFAULT NULL,
  `SCOPE_TYPE_` varchar(64) COLLATE utf8_bin DEFAULT NULL,
  `SEARCH_KEY_` varchar(255) COLLATE utf8_bin DEFAULT NULL,
  `SEARCH_KEY2_` varchar(255) COLLATE utf8_bin DEFAULT NULL,
  `CREATE_TIME_` datetime(3) DEFAULT NULL,
  `COMPLETE_TIME_` datetime(3) DEFAULT NULL,
  `STATUS_` varchar(255) COLLATE utf8_bin DEFAULT NULL,
  `RESULT_DOC_ID_` varchar(64) COLLATE utf8_bin DEFAULT NULL,
  `TENANT_ID_` varchar(255) COLLATE utf8_bin DEFAULT '',
  PRIMARY KEY (`ID_`) USING BTREE,
  KEY `FLW_IDX_BATCH_PART` (`BATCH_ID_`) USING BTREE,
  CONSTRAINT `FLW_FK_BATCH_PART_PARENT` FOREIGN KEY (`BATCH_ID_`) REFERENCES `flw_ru_batch` (`ID_`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_bin ROW_FORMAT=DYNAMIC;

DROP TABLE IF EXISTS `gen_table`;

CREATE TABLE `gen_table` (
  `table_id` bigint(20) NOT NULL COMMENT '编号',
  `data_name` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '数据源名称',
  `table_name` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '表名称',
  `table_comment` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '表描述',
  `sub_table_name` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '关联子表的表名',
  `sub_table_fk_name` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '子表关联的外键名',
  `class_name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '实体类名称',
  `tpl_category` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT 'crud' COMMENT '使用的模板（crud单表操作 tree树表操作）',
  `package_name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '生成包路径',
  `module_name` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '生成模块名',
  `business_name` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '生成业务名',
  `function_name` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '生成功能名',
  `function_author` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '生成功能作者',
  `source_type` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT 'import' COMMENT '来源类型：import-从数据库导入/design-在线设计',
  `design_id` bigint(20) DEFAULT NULL COMMENT '关联的Online设计ID',
  `design_content` mediumtext COLLATE utf8mb4_unicode_ci COMMENT 'Online设计JSON内容',
  `is_online_form` char(1) COLLATE utf8mb4_unicode_ci DEFAULT '0' COMMENT '是否启用Online表单：0-否/1-是',
  `gen_type` char(1) COLLATE utf8mb4_unicode_ci DEFAULT '0' COMMENT '生成代码方式（0zip压缩包 1自定义路径）',
  `gen_path` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT '/' COMMENT '生成路径（不填默认项目路径）',
  `options` varchar(1000) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '其它生成选项',
  `create_dept` bigint(20) DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) DEFAULT NULL COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` bigint(20) DEFAULT NULL COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`table_id`) USING BTREE,
  KEY `idx_gen_table_design_id` (`design_id`) USING BTREE,
  KEY `idx_gen_table_source_type` (`source_type`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='代码生成业务表';


DROP TABLE IF EXISTS `gen_table_column`;

CREATE TABLE `gen_table_column` (
  `column_id` bigint(20) NOT NULL COMMENT '编号',
  `table_id` bigint(20) DEFAULT NULL COMMENT '归属表编号',
  `column_name` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '列名称',
  `column_comment` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '列描述',
  `column_type` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '列类型',
  `java_type` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'JAVA类型',
  `java_field` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'JAVA字段名',
  `is_pk` char(1) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '是否主键（1是）',
  `is_increment` char(1) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '是否自增（1是）',
  `is_required` char(1) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '是否必填（1是）',
  `is_insert` char(1) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '是否为插入字段（1是）',
  `is_edit` char(1) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '是否编辑字段（1是）',
  `is_list` char(1) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '是否列表字段（1是）',
  `is_query` char(1) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '是否查询字段（1是）',
  `query_type` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT 'EQ' COMMENT '查询方式（等于、不等于、大于、小于、范围）',
  `html_type` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '显示类型（文本框、文本域、下拉框、复选框、单选框、日期控件）',
  `dict_type` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '字典类型',
  `form_rules` mediumtext COLLATE utf8mb4_unicode_ci COMMENT '表单验证规则JSON',
  `link_config` mediumtext COLLATE utf8mb4_unicode_ci COMMENT '字段联动配置JSON',
  `form_span` int(11) DEFAULT '24' COMMENT '表单栅格宽度(1-24)',
  `is_readonly` char(1) COLLATE utf8mb4_unicode_ci DEFAULT '0' COMMENT '是否只读：0-否/1-是',
  `field_tip` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '字段提示信息',
  `sort` int(11) DEFAULT NULL COMMENT '排序',
  `create_dept` bigint(20) DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) DEFAULT NULL COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` bigint(20) DEFAULT NULL COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`column_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='代码生成业务表字段';







DROP TABLE IF EXISTS `gen_table_design_history`;

CREATE TABLE `gen_table_design_history` (
  `history_id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '历史记录ID',
  `table_id` bigint(20) NOT NULL COMMENT '关联的gen_table ID',
  `design_content` mediumtext COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '设计JSON内容',
  `version` int(11) DEFAULT '1' COMMENT '版本号',
  `create_by` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `remark` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`history_id`) USING BTREE,
  KEY `idx_design_history_table_id` (`table_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='代码生成表设计历史记录';

DROP TABLE IF EXISTS `im_conversation_setting`;

CREATE TABLE `im_conversation_setting` (
  `id` bigint(20) NOT NULL COMMENT '主键',
  `user_id` bigint(20) NOT NULL COMMENT '所属用户 ID',
  `chat_type` varchar(10) NOT NULL COMMENT '会话类型: PRIVATE/GROUP',
  `target_id` bigint(20) NOT NULL COMMENT '目标 ID（私聊=对方 userId，群聊=groupId）',
  `is_pinned` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否置顶: 0=否 1=是',
  `pinned_at` datetime(3) DEFAULT NULL COMMENT '置顶时间（用于多会话置顶排序）',
  `is_muted` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否免打扰: 0=否 1=是',
  `tenant_id` varchar(20) DEFAULT '000000' COMMENT '租户编号',
  `create_dept` bigint(20) DEFAULT NULL COMMENT '鍒涘缓閮ㄩ棬',
  `create_by` bigint(20) DEFAULT NULL COMMENT '创建者',
  `create_time` datetime(3) DEFAULT NULL COMMENT '创建时间',
  `update_by` bigint(20) DEFAULT NULL COMMENT '更新者',
  `update_time` datetime(3) DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uk_user_chat_target` (`user_id`,`chat_type`,`target_id`,`tenant_id`) USING BTREE,
  KEY `idx_user_pinned` (`user_id`,`is_pinned`,`pinned_at`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC COMMENT='IM 会话级配置（置顶/免打扰）';

DROP TABLE IF EXISTS `im_favorite`;

CREATE TABLE `im_favorite` (
  `id` bigint(20) NOT NULL COMMENT '主键',
  `user_id` bigint(20) NOT NULL COMMENT '收藏者用户 ID',
  `message_id` bigint(20) NOT NULL COMMENT '被收藏的消息 ID',
  `chat_type` varchar(10) NOT NULL COMMENT '来源会话类型: PRIVATE/GROUP',
  `target_id` bigint(20) NOT NULL COMMENT '来源会话目标 ID',
  `from_user_id` bigint(20) DEFAULT NULL COMMENT '消息原发送者（冗余便于列表展示）',
  `msg_type` varchar(20) DEFAULT NULL COMMENT '消息类型（冗余）',
  `content_snippet` varchar(500) DEFAULT NULL COMMENT '内容摘要（避免列表 JOIN im_message）',
  `tenant_id` varchar(20) DEFAULT '000000' COMMENT '租户编号',
  `create_dept` bigint(20) DEFAULT NULL COMMENT '鍒涘缓閮ㄩ棬',
  `create_by` bigint(20) DEFAULT NULL COMMENT '创建者',
  `create_time` datetime(3) DEFAULT NULL COMMENT '创建时间',
  `update_by` bigint(20) DEFAULT NULL COMMENT '鏇存柊鑰',
  `update_time` datetime(3) DEFAULT NULL COMMENT '鏇存柊鏃堕棿',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uk_user_message` (`user_id`,`message_id`,`tenant_id`) USING BTREE,
  KEY `idx_user_create` (`user_id`,`create_time`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC COMMENT='IM 用户收藏消息';

DROP TABLE IF EXISTS `im_friend`;

CREATE TABLE `im_friend` (
  `id` bigint(20) NOT NULL COMMENT '主键',
  `tenant_id` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT '000000' COMMENT '租户编号',
  `user_id` bigint(20) NOT NULL COMMENT '用户ID',
  `friend_user_id` bigint(20) NOT NULL COMMENT '好友用户ID',
  `create_dept` bigint(20) DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) DEFAULT NULL COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` bigint(20) DEFAULT NULL COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uk_im_friend` (`tenant_id`,`user_id`,`friend_user_id`) USING BTREE,
  KEY `idx_im_friend_user` (`tenant_id`,`user_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='IM好友关系';


DROP TABLE IF EXISTS `im_group`;

CREATE TABLE `im_group` (
  `group_id` bigint(20) NOT NULL COMMENT '群ID',
  `tenant_id` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT '000000' COMMENT '租户编号',
  `group_name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '群名称',
  `avatar` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '群头像',
  `owner_user_id` bigint(20) NOT NULL COMMENT '群主用户ID',
  `status` char(1) COLLATE utf8mb4_unicode_ci DEFAULT '0' COMMENT '状态（0正常 1解散）',
  `create_dept` bigint(20) DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) DEFAULT NULL COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` bigint(20) DEFAULT NULL COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`group_id`) USING BTREE,
  KEY `idx_im_group_tenant` (`tenant_id`,`status`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='IM群组';


DROP TABLE IF EXISTS `im_group_member`;

CREATE TABLE `im_group_member` (
  `id` bigint(20) NOT NULL COMMENT '主键',
  `tenant_id` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT '000000' COMMENT '租户编号',
  `group_id` bigint(20) NOT NULL COMMENT '群ID',
  `user_id` bigint(20) NOT NULL COMMENT '成员用户ID',
  `join_time` datetime DEFAULT NULL COMMENT '加入时间',
  `create_dept` bigint(20) DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) DEFAULT NULL COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` bigint(20) DEFAULT NULL COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uk_group_user` (`group_id`,`user_id`) USING BTREE,
  KEY `idx_igm_user` (`tenant_id`,`user_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='IM群成员';


DROP TABLE IF EXISTS `im_message`;

CREATE TABLE `im_message` (
  `message_id` bigint(20) NOT NULL COMMENT '消息主键',
  `tenant_id` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT '000000' COMMENT '租户编号',
  `from_user_id` bigint(20) NOT NULL COMMENT '发送人',
  `to_user_id` bigint(20) DEFAULT NULL COMMENT '接收人(私聊)',
  `group_id` bigint(20) DEFAULT NULL COMMENT '群ID(群聊)',
  `content` text COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '消息内容',
  `msg_type` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT 'text' COMMENT '消息类型',
  `is_read` char(1) COLLATE utf8mb4_unicode_ci DEFAULT '0' COMMENT '私聊已读(0否1是)；群聊MVP不使用',
  `revoked` char(1) COLLATE utf8mb4_unicode_ci DEFAULT '0' COMMENT '是否撤回（0否 1是）',
  `forward_from` bigint(20) DEFAULT NULL COMMENT '杞?彂鏉ユ簮娑堟伅ID',
  `client_msg_id` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '客户端消息ID（重发幂等）',
  `mention_user_ids` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '被@的用户ID列表（JSON数组字符串）',
  `create_dept` bigint(20) DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) DEFAULT NULL COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` bigint(20) DEFAULT NULL COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `reply_message_id` bigint(20) DEFAULT NULL COMMENT '引用的消息 ID',
  `reply_snippet` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '引用消息内容摘要',
  PRIMARY KEY (`message_id`) USING BTREE,
  UNIQUE KEY `uk_client_msg_id` (`tenant_id`,`client_msg_id`) USING BTREE,
  KEY `idx_im_msg_private` (`tenant_id`,`from_user_id`,`to_user_id`,`create_time`) USING BTREE,
  KEY `idx_im_msg_to` (`tenant_id`,`to_user_id`,`create_time`) USING BTREE,
  KEY `idx_im_msg_group` (`tenant_id`,`group_id`,`create_time`) USING BTREE,
  KEY `idx_private_unread` (`tenant_id`,`to_user_id`,`is_read`,`from_user_id`,`create_time`) USING BTREE,
  KEY `idx_group_unread` (`tenant_id`,`group_id`,`is_read`) USING BTREE,
  KEY `idx_reply_msg` (`reply_message_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='IM消息';


DROP TABLE IF EXISTS `jimu_dict`;

CREATE TABLE `jimu_dict` (
  `id` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL,
  `dict_name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '字典名称',
  `dict_code` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '字典编码',
  `description` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '描述',
  `del_flag` int(1) DEFAULT NULL COMMENT '删除状态',
  `create_by` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '创建人',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '更新人',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `type` int(1) unsigned zerofill DEFAULT '0' COMMENT '字典类型0为string,1为number',
  `tenant_id` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '多租户标识',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uk_sd_dict_code` (`dict_code`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;


DROP TABLE IF EXISTS `jimu_dict_item`;

CREATE TABLE `jimu_dict_item` (
  `id` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL,
  `dict_id` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '字典id',
  `item_text` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '字典项文本',
  `item_value` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '字典项值',
  `description` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '描述',
  `sort_order` int(10) DEFAULT NULL COMMENT '排序',
  `status` int(11) DEFAULT NULL COMMENT '状态（1启用 0不启用）',
  `create_by` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `create_time` datetime DEFAULT NULL,
  `update_by` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `update_time` datetime DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_sdi_role_dict_id` (`dict_id`) USING BTREE,
  KEY `idx_sdi_role_sort_order` (`sort_order`) USING BTREE,
  KEY `idx_sdi_status` (`status`) USING BTREE,
  KEY `idx_sdi_dict_val` (`dict_id`,`item_value`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;




DROP TABLE IF EXISTS `jimu_report`;

CREATE TABLE `jimu_report` (
  `id` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '主键',
  `code` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '编码',
  `name` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '名称',
  `note` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '说明',
  `status` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '状态',
  `type` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '类型',
  `json_str` longtext COLLATE utf8mb4_unicode_ci COMMENT 'json字符串',
  `api_url` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '请求地址',
  `thumb` mediumtext COLLATE utf8mb4_unicode_ci COMMENT '缩略图',
  `create_by` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '创建人',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '修改人',
  `update_time` datetime DEFAULT NULL COMMENT '修改时间',
  `del_flag` tinyint(1) DEFAULT NULL COMMENT '删除标识0-正常,1-已删除',
  `api_method` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '请求方法0-get,1-post',
  `api_code` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '请求编码',
  `template` tinyint(1) DEFAULT NULL COMMENT '是否是模板 0-是,1-不是',
  `view_count` bigint(15) DEFAULT '0' COMMENT '浏览次数',
  `css_str` mediumtext COLLATE utf8mb4_unicode_ci COMMENT 'css增强',
  `js_str` mediumtext COLLATE utf8mb4_unicode_ci COMMENT 'js增强',
  `py_str` mediumtext COLLATE utf8mb4_unicode_ci COMMENT 'py增强',
  `tenant_id` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '多租户标识',
  `update_count` int(11) DEFAULT '0' COMMENT '乐观锁版本',
  `submit_form` tinyint(1) DEFAULT NULL COMMENT '是否填报报表 0不是,1是',
  `is_multi_sheet` tinyint(4) DEFAULT NULL COMMENT '是否多sheet报表 1是 0否',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uniq_jmreport_code` (`code`) USING BTREE,
  KEY `uniq_jmreport_createby` (`create_by`) USING BTREE,
  KEY `uniq_jmreport_delflag` (`del_flag`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='在线excel设计器';



DROP TABLE IF EXISTS `jimu_report_category`;

CREATE TABLE `jimu_report_category` (
  `id` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '主键',
  `name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '分类名称',
  `parent_id` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '父级id',
  `iz_leaf` int(1) DEFAULT NULL COMMENT '是否为叶子节点(0 否 1是)',
  `source_type` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '来源类型( report 积木报表 screen 大屏  drag 仪表盘)',
  `create_by` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '创建人',
  `create_time` timestamp NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '更新人',
  `update_time` timestamp NULL DEFAULT NULL COMMENT '更新时间',
  `tenant_id` varchar(11) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '租户id',
  `del_flag` int(1) DEFAULT NULL COMMENT '删除状态(0未删除，1已删除，2临时删除)',
  `sort_no` int(11) DEFAULT NULL COMMENT '排序',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='分类';


DROP TABLE IF EXISTS `jimu_report_data_source`;

CREATE TABLE `jimu_report_data_source` (
  `id` varchar(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '数据源名称',
  `report_id` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '报表_id',
  `code` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '编码',
  `remark` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `db_type` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '数据库类型',
  `db_driver` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '驱动类',
  `db_url` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '数据源地址',
  `db_username` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '用户名',
  `db_password` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '密码',
  `create_by` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '创建人',
  `create_time` datetime DEFAULT NULL COMMENT '创建日期',
  `update_by` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '更新人',
  `update_time` datetime DEFAULT NULL COMMENT '更新日期',
  `connect_times` int(11) DEFAULT '0' COMMENT '连接失败次数',
  `tenant_id` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '多租户标识',
  `type` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '类型(report:报表;drag:仪表盘)',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_jmdatasource_report_id` (`report_id`) USING BTREE,
  KEY `idx_jmdatasource_code` (`code`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;


DROP TABLE IF EXISTS `jimu_report_db`;

CREATE TABLE `jimu_report_db` (
  `id` varchar(36) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'id',
  `jimu_report_id` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '主键字段',
  `create_by` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '创建人登录名称',
  `update_by` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '更新人登录名称',
  `create_time` datetime DEFAULT NULL COMMENT '创建日期',
  `update_time` datetime DEFAULT NULL COMMENT '更新日期',
  `db_code` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '数据集编码',
  `db_ch_name` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '数据集名字',
  `db_type` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '数据源类型',
  `db_table_name` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '数据库表名',
  `db_dyn_sql` longtext COLLATE utf8mb4_unicode_ci COMMENT '动态查询SQL',
  `db_key` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '数据源KEY',
  `tb_db_key` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '填报数据源',
  `tb_db_table_name` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '填报数据表',
  `java_type` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'java类数据集  类型（spring:springkey,class:java类名）',
  `java_value` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'java类数据源  数值（bean key/java类名）',
  `api_url` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '请求地址',
  `api_method` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '请求方法0-get,1-post',
  `is_list` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT '0' COMMENT '是否是列表0否1是 默认0',
  `is_page` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '是否作为分页,0:不分页，1:分页',
  `db_source` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '数据源',
  `db_source_type` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '数据库类型 MYSQL ORACLE SQLSERVER',
  `json_data` mediumtext COLLATE utf8mb4_unicode_ci COMMENT 'json数据，直接解析json内容',
  `api_convert` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'api转换器',
  `iz_shared_source` int(1) DEFAULT NULL COMMENT '是否为共享数据源(0 否 1 是)',
  `jimu_shared_source_id` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '指向共享数据集的id',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_jmreportdb_db_key` (`db_key`) USING BTREE,
  KEY `idx_jimu_report_id` (`jimu_report_id`) USING BTREE,
  KEY `idx_db_source_id` (`db_source`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;



DROP TABLE IF EXISTS `jimu_report_db_field`;

CREATE TABLE `jimu_report_db_field` (
  `id` varchar(36) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'id',
  `create_by` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '创建人登录名称',
  `create_time` datetime DEFAULT NULL COMMENT '创建日期',
  `update_by` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '更新人登录名称',
  `update_time` datetime DEFAULT NULL COMMENT '更新日期',
  `jimu_report_db_id` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '数据源ID',
  `field_name` varchar(80) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '字段名',
  `field_name_physics` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '物理字段名（文件数据集使用，存的是excel的字段标题）',
  `field_text` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '字段文本',
  `widget_type` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '控件类型',
  `widget_width` int(10) DEFAULT NULL COMMENT '控件宽度',
  `order_num` int(3) DEFAULT NULL COMMENT '排序',
  `search_flag` int(3) DEFAULT '0' COMMENT '查询标识0否1是 默认0',
  `search_mode` int(3) DEFAULT NULL COMMENT '查询模式1简单2范围',
  `dict_code` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '字典编码支持从表中取数据',
  `search_value` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '查询默认值',
  `search_format` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '查询时间格式化表达式',
  `ext_json` mediumtext COLLATE utf8mb4_unicode_ci COMMENT '参数配置',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_jrdf_jimu_report_db_id` (`jimu_report_db_id`) USING BTREE,
  KEY `idx_dbfield_order_num` (`order_num`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;











DROP TABLE IF EXISTS `jimu_report_db_param`;

CREATE TABLE `jimu_report_db_param` (
  `id` varchar(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `jimu_report_head_id` varchar(36) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '动态报表ID',
  `param_name` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '参数字段',
  `param_txt` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '参数文本',
  `param_value` varchar(1000) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '参数默认值',
  `order_num` int(11) DEFAULT NULL COMMENT '排序',
  `create_by` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '创建人登录名称',
  `create_time` datetime DEFAULT NULL COMMENT '创建日期',
  `update_by` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '更新人登录名称',
  `update_time` datetime DEFAULT NULL COMMENT '更新日期',
  `search_flag` int(1) DEFAULT NULL COMMENT '查询标识0否1是 默认0',
  `widget_type` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '查询控件类型',
  `search_mode` int(1) DEFAULT NULL COMMENT '查询模式1简单2范围',
  `dict_code` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '字典',
  `search_format` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '查询时间格式化表达式',
  `ext_json` mediumtext COLLATE utf8mb4_unicode_ci COMMENT '参数配置',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_jrdp_jimu_report_head_id` (`jimu_report_head_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;


DROP TABLE IF EXISTS `jimu_report_export_job`;

CREATE TABLE `jimu_report_export_job` (
  `id` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '主键',
  `name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '任务名称',
  `begin_time` datetime DEFAULT NULL COMMENT '开始时间',
  `end_time` datetime DEFAULT NULL COMMENT '结束时间',
  `exec_interval` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '执行频率',
  `report_conf` text COLLATE utf8mb4_unicode_ci COMMENT '导出报表配置',
  `last_run_time` datetime DEFAULT NULL COMMENT '最后执行时间',
  `receiver_email` text COLLATE utf8mb4_unicode_ci COMMENT '接收通知的邮件',
  `file_sync_path` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '文件同步路径',
  `status` int(11) DEFAULT NULL COMMENT '状态(0:停止;1:启动)',
  `create_by` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '创建人',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '修改人',
  `update_time` datetime DEFAULT NULL COMMENT '修改时间',
  `tenant_id` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '多租户标识',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='积木报表导出计划表';


DROP TABLE IF EXISTS `jimu_report_export_log`;

CREATE TABLE `jimu_report_export_log` (
  `id` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL,
  `batch_no` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '批次编号',
  `export_channel` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '导出渠道',
  `export_from` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '发起来源',
  `from_id` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '来源id',
  `export_type` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '导出类型',
  `report_id` text COLLATE utf8mb4_unicode_ci COMMENT '报表id',
  `download_path` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '下载路径',
  `status` varchar(15) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '状态',
  `err_msg` text COLLATE utf8mb4_unicode_ci COMMENT '错误消息',
  `create_by` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '创建人',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `tenant_id` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '多租户标识',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='积木报表自动导出记录表';




DROP TABLE IF EXISTS `jimu_report_ext_data`;

CREATE TABLE `jimu_report_ext_data` (
  `id` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '主键ID',
  `biz_type` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '业务类型标识，如 report_share、temp_config 等',
  `name` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '名称，展示用',
  `descr` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '描述信息',
  `tags` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '标签，多个用逗号分隔',
  `data_value` longtext COLLATE utf8mb4_unicode_ci COMMENT '实际存储内容',
  `metadata` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '元数据，用于存储补充信息',
  `status` tinyint(4) DEFAULT '1' COMMENT '状态标识：1正常 0禁用',
  `create_by` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '创建人',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_by` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '修改人',
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_biz` (`biz_type`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='通用扩展数据表';


DROP TABLE IF EXISTS `jimu_report_icon_lib`;

CREATE TABLE `jimu_report_icon_lib` (
  `id` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '主键',
  `name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '图片名称',
  `type` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '图片类型',
  `image_url` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '图片地址',
  `create_by` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '创建人',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '更新人',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `tenant_id` int(11) DEFAULT NULL COMMENT '租户id',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='积木图库表';




DROP TABLE IF EXISTS `jimu_report_link`;

CREATE TABLE `jimu_report_link` (
  `id` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '主键id',
  `report_id` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '积木设计器id',
  `parameter` text COLLATE utf8mb4_unicode_ci COMMENT '参数',
  `eject_type` varchar(1) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '弹出方式（0 当前页面 1 新窗口）',
  `link_name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '链接名称',
  `api_method` varchar(1) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '请求方法0-get,1-post',
  `link_type` varchar(1) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '链接方式(0 网络报表 1 网络连接 2 图表联动)',
  `api_url` varchar(1000) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '外网api',
  `link_chart_id` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '联动图表的ID',
  `expression` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '表达式',
  `requirement` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '条件',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `uniq_link_reportid` (`report_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='超链接配置表';


DROP TABLE IF EXISTS `jimu_report_map`;

CREATE TABLE `jimu_report_map` (
  `id` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '主键',
  `label` varchar(125) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '地图名称',
  `name` varchar(125) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '地图编码',
  `data` longtext COLLATE utf8mb4_unicode_ci COMMENT '地图数据',
  `create_by` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '创建人',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '修改人',
  `update_time` datetime DEFAULT NULL COMMENT '修改时间',
  `del_flag` varchar(1) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '0表示未删除,1表示删除',
  `sys_org_code` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '所属部门',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uniq_jmreport_map_name` (`name`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='地图配置表';








DROP TABLE IF EXISTS `jimu_report_share`;

CREATE TABLE `jimu_report_share` (
  `id` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '主键',
  `report_id` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '在线excel设计器id',
  `preview_url` varchar(1000) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预览地址',
  `preview_lock` varchar(4) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '密码锁',
  `last_update_time` datetime DEFAULT NULL COMMENT '最后更新时间',
  `term_of_validity` varchar(1) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '有效期(0:永久有效，1:1天，2:7天)',
  `status` varchar(1) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '是否过期(0未过期，1已过期)',
  `preview_lock_status` varchar(1) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '密码锁状态(0不存在密码锁，1存在密码锁)',
  `share_token` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '分享token',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uniq_report_id` (`report_id`) USING BTREE,
  KEY `idx_jrs_share_token` (`share_token`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='积木报表预览权限表';


DROP TABLE IF EXISTS `jimu_report_sheet`;

CREATE TABLE `jimu_report_sheet` (
  `id` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '主键（Sheet ID）',
  `report_id` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '报表ID',
  `sheet_name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Sheet名称',
  `sheet_order` int(11) NOT NULL COMMENT '排序（可以为负数，负数表示在默认sheet前面）',
  `json_str` longtext COLLATE utf8mb4_unicode_ci COMMENT '该sheet的完整jsonStr',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `create_by` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '创建人',
  `update_by` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '更新人',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_report_id` (`report_id`) USING BTREE,
  KEY `idx_sheet_order` (`report_id`,`sheet_order`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='报表Sheet表';


DROP TABLE IF EXISTS `mq_compensation_record`;

CREATE TABLE `mq_compensation_record` (
  `id` bigint(20) NOT NULL COMMENT '主键ID',
  `message_id` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '关联消息ID',
  `business_type` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '业务类型',
  `business_id` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '业务ID',
  `compensation_status` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'PENDING' COMMENT '补偿状态: PENDING/SUCCESS/FAILED',
  `compensation_method` varchar(256) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '补偿方法(全限定类名.方法名)',
  `compensation_params` text COLLATE utf8mb4_unicode_ci COMMENT '补偿参数JSON',
  `retry_count` int(11) NOT NULL DEFAULT '0' COMMENT '已重试次数',
  `max_retry` int(11) NOT NULL DEFAULT '5' COMMENT '最大重试次数',
  `next_retry_time` datetime DEFAULT NULL COMMENT '下次重试时间',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_compensation_status` (`compensation_status`,`next_retry_time`) USING BTREE,
  KEY `idx_business` (`business_type`,`business_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='补偿记录表';

DROP TABLE IF EXISTS `mq_dead_letter_record`;

CREATE TABLE `mq_dead_letter_record` (
  `id` bigint(20) NOT NULL COMMENT '主键ID',
  `message_id` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '原始消息ID',
  `exchange` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '原始交换机',
  `routing_key` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '原始路由键',
  `message_body` text COLLATE utf8mb4_unicode_ci COMMENT '消息体JSON',
  `error_message` text COLLATE utf8mb4_unicode_ci COMMENT '错误信息',
  `retry_count` int(11) NOT NULL DEFAULT '0' COMMENT '已重试次数',
  `status` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'PENDING' COMMENT '状态: PENDING/RESOLVED/RESENT',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `message_type` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '消息类型全限定名(人工重投反序列化用)',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_status` (`status`) USING BTREE,
  KEY `idx_create_time` (`create_time`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='死信记录表';


DROP TABLE IF EXISTS `mq_message_record`;

CREATE TABLE `mq_message_record` (
  `id` bigint(20) NOT NULL COMMENT '主键ID',
  `message_id` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '消息唯一ID',
  `exchange` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '交换机名称',
  `routing_key` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '路由键',
  `message_body` text COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '消息体JSON',
  `message_type` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '消息类型全限定名(补偿重投时类型化反序列化用)',
  `status` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'SENDING' COMMENT '状态: SENDING/SENT/CONSUMED/FAILED',
  `retry_count` int(11) NOT NULL DEFAULT '0' COMMENT '重试次数',
  `max_retry` int(11) NOT NULL DEFAULT '3' COMMENT '最大重试次数',
  `next_retry_time` datetime DEFAULT NULL COMMENT '下次重试时间',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uk_message_id` (`message_id`) USING BTREE,
  KEY `idx_status_create` (`status`,`create_time`) USING BTREE,
  KEY `idx_next_retry` (`next_retry_time`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='消息记录表';



DROP TABLE IF EXISTS `onl_drag_comp`;

CREATE TABLE `onl_drag_comp` (
  `id` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '主键',
  `parent_id` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `comp_name` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '组件名称',
  `comp_type` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `icon` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '图标',
  `order_num` int(11) DEFAULT NULL COMMENT '排序',
  `type_id` int(11) DEFAULT NULL COMMENT '组件类型',
  `comp_config` longtext COLLATE utf8mb4_unicode_ci COMMENT '组件配置',
  `status` varchar(2) COLLATE utf8mb4_unicode_ci DEFAULT '0' COMMENT '状态0:无效 1:有效',
  `create_by` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '创建人登录名称',
  `create_time` datetime DEFAULT NULL COMMENT '创建日期',
  `update_by` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '更新人登录名称',
  `update_time` datetime DEFAULT NULL COMMENT '更新日期',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='组件库';



DROP TABLE IF EXISTS `onl_drag_dataset_head`;

CREATE TABLE `onl_drag_dataset_head` (
  `id` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'id',
  `name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '名称',
  `code` varchar(36) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '编码',
  `parent_id` varchar(36) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '父id',
  `db_source` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '动态数据源',
  `query_sql` varchar(5000) COLLATE utf8mb4_unicode_ci DEFAULT '0' COMMENT '查询数据SQL',
  `content` varchar(1000) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '描述',
  `iz_agent` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT '0' COMMENT 'iz_agent',
  `data_type` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '数据类型',
  `api_method` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'api方法：get/post',
  `create_time` datetime DEFAULT NULL,
  `create_by` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `update_time` datetime DEFAULT NULL,
  `update_by` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `low_app_id` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '应用ID',
  `tenant_id` int(10) DEFAULT NULL COMMENT '租户ID',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;


DROP TABLE IF EXISTS `onl_drag_dataset_item`;

CREATE TABLE `onl_drag_dataset_item` (
  `id` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'id',
  `head_id` varchar(36) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '主表ID',
  `field_name` varchar(36) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '字段名',
  `field_txt` varchar(1000) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '字段文本',
  `field_type` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '字段类型',
  `widget_type` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '控件类型',
  `dict_code` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '字典Code',
  `dict_table` varchar(125) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `dict_text` varchar(125) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `iz_show` varchar(5) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '是否列表显示',
  `iz_search` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '是否查询',
  `iz_total` varchar(5) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '是否计算总计（仅对数值有效）',
  `search_mode` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '查询模式',
  `order_num` int(11) DEFAULT NULL COMMENT '排序',
  `create_by` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '创建人',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '修改人',
  `update_time` datetime DEFAULT NULL COMMENT '修改时间',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_oddi_head_id` (`head_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;




DROP TABLE IF EXISTS `onl_drag_dataset_param`;

CREATE TABLE `onl_drag_dataset_param` (
  `id` varchar(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `head_id` varchar(36) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '动态报表ID',
  `param_name` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '参数字段',
  `param_txt` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '参数文本',
  `param_value` varchar(1000) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '参数默认值',
  `order_num` int(11) DEFAULT NULL COMMENT '排序',
  `iz_search` int(11) DEFAULT NULL COMMENT '查询标识0否1是 默认0',
  `widget_type` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '查询控件类型',
  `search_mode` int(11) DEFAULT NULL COMMENT '查询模式1简单2范围',
  `dict_code` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '字典',
  `create_by` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '创建人登录名称',
  `create_time` datetime DEFAULT NULL COMMENT '创建日期',
  `update_by` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '更新人登录名称',
  `update_time` datetime DEFAULT NULL COMMENT '更新日期',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_oddp_head_id` (`head_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;


DROP TABLE IF EXISTS `onl_drag_page`;

CREATE TABLE `onl_drag_page` (
  `id` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '主键',
  `name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '界面名称',
  `path` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '访问路径',
  `background_color` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '背景色',
  `background_image` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '背景图',
  `design_type` int(1) DEFAULT NULL COMMENT '设计模式(1:pc,2:手机,3:平板)',
  `theme` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '主题色',
  `style` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '面板主题',
  `cover_url` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '封面图',
  `des_json` varchar(1000) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '仪表盘主配置JSON',
  `template` longtext COLLATE utf8mb4_unicode_ci COMMENT '布局json',
  `protection_code` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '保护码',
  `type` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '文件夹类',
  `iz_template` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT '0' COMMENT '是否模板(1:是；0不是)',
  `create_by` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '创建人登录名称',
  `create_time` datetime DEFAULT NULL COMMENT '创建日期',
  `update_by` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '更新人登录名称',
  `update_time` datetime DEFAULT NULL COMMENT '更新日期',
  `low_app_id` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '应用ID',
  `tenant_id` int(10) DEFAULT NULL COMMENT '租户ID',
  `update_count` int(10) DEFAULT '1',
  `visits_num` int(11) DEFAULT NULL COMMENT '访问次数',
  `del_flag` int(11) DEFAULT NULL COMMENT '删除状态( 0未删除 1已删除)',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='可视化拖拽界面';




DROP TABLE IF EXISTS `onl_drag_page_comp`;

CREATE TABLE `onl_drag_page_comp` (
  `id` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '主键',
  `parent_id` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '父组件ID',
  `page_Id` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '界面ID',
  `comp_id` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '组件库ID',
  `component` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '组件名称',
  `config` longtext COLLATE utf8mb4_unicode_ci COMMENT '组件配置',
  `create_by` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '创建人登录名称',
  `create_time` datetime DEFAULT NULL COMMENT '创建日期',
  `update_by` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '更新人登录名称',
  `update_time` datetime DEFAULT NULL COMMENT '更新日期',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='可视化拖拽页面组件';











DROP TABLE IF EXISTS `onl_drag_share`;

CREATE TABLE `onl_drag_share` (
  `id` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '主键',
  `drag_id` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '在线仪表盘设计器id',
  `preview_url` varchar(1000) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预览地址',
  `preview_lock` varchar(4) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '密码锁',
  `last_update_time` datetime DEFAULT NULL COMMENT '最后更新时间',
  `term_of_validity` varchar(1) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '有效期(0:永久有效，1:1天，7:7天)',
  `status` varchar(1) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '是否过期(0未过期，1已过期)',
  `preview_lock_status` varchar(1) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '是否为密码锁(0 否,1是)',
  `share_token` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '分享token',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uniq_ods_drag_id` (`drag_id`) USING BTREE COMMENT '仪表盘id唯一索引'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='仪表盘预览分享表';


DROP TABLE IF EXISTS `onl_drag_table_relation`;

CREATE TABLE `onl_drag_table_relation` (
  `id` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '主键',
  `aggregation_name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '聚合表名称',
  `aggregation_desc` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '聚合表描述',
  `relation_forms` longtext COLLATE utf8mb4_unicode_ci COMMENT '关联表单',
  `filter_condition` longtext COLLATE utf8mb4_unicode_ci COMMENT '过滤条件',
  `header_fields` longtext COLLATE utf8mb4_unicode_ci COMMENT '表头字段',
  `calculate_fields` longtext COLLATE utf8mb4_unicode_ci COMMENT '公式字段',
  `validate_info` longtext COLLATE utf8mb4_unicode_ci COMMENT '校验信息',
  `del_flag` tinyint(1) DEFAULT NULL COMMENT '删除状态(0-正常,1-已删除)',
  `low_app_id` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '应用ID',
  `tenant_id` int(11) DEFAULT NULL COMMENT '租户ID',
  `create_by` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '创建人登录名称',
  `create_time` datetime DEFAULT NULL COMMENT '创建日期',
  `update_by` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '更新人登录名称',
  `update_time` datetime DEFAULT NULL COMMENT '更新日期',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_aggregation_name` (`aggregation_name`) USING BTREE,
  KEY `idx_del_flag` (`del_flag`) USING BTREE,
  KEY `idx_tenant_id` (`tenant_id`) USING BTREE,
  KEY `idx_create_by` (`create_by`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='仪表盘聚合表';

DROP TABLE IF EXISTS `pay_invoice`;

CREATE TABLE `pay_invoice` (
  `invoice_id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '发票ID',
  `order_number` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '订单号',
  `invoice_type` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '发票类型',
  `invoice_header` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '发票抬头',
  `invoice_number` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '纳税人识别号',
  `invoice_phone` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '收票人手机号',
  `invoice_email` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '收票人邮箱',
  `invoice_remark` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '发票备注',
  `tenant_id` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT '000000' COMMENT '租户编号',
  `create_dept` bigint(20) DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) DEFAULT NULL COMMENT '创建人',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_by` bigint(20) DEFAULT NULL COMMENT '更新人',
  `update_time` datetime DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `remark` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`invoice_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='发票表';


DROP TABLE IF EXISTS `pay_order`;

CREATE TABLE `pay_order` (
  `order_id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '订单ID',
  `order_number` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '商户订单号',
  `third_number` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '第三方订单号',
  `order_status` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '订单状态',
  `biz_type` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '业务类型 SO_ORDER/AR_RECEIPT',
  `biz_id` bigint(20) DEFAULT NULL COMMENT '业务单据ID(销售订单ID等)',
  `client_id` bigint(20) DEFAULT NULL COMMENT '客户ID(AR 收款核销用)',
  `total_amount` decimal(18,2) DEFAULT '0.00' COMMENT '璁㈠崟鎬婚噾棰濓紙鍗曚綅锛氬厓锛',
  `actual_amount` decimal(18,2) DEFAULT '0.00' COMMENT '瀹為檯鏀?粯閲戦?锛堝崟浣嶏細鍏冿級',
  `order_content` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '订单内容',
  `order_message` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '负载信息',
  `pay_type` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '支付方式',
  `pay_time` datetime DEFAULT NULL COMMENT '支付时间',
  `pay_by` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '支付人',
  `tenant_id` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT '000000' COMMENT '租户编号',
  `create_dept` bigint(20) DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) DEFAULT NULL COMMENT '创建人',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_by` bigint(20) DEFAULT NULL COMMENT '更新人',
  `update_time` datetime DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `remark` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`order_id`) USING BTREE,
  KEY `idx_order_number` (`order_number`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=28 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='订单表';


DROP TABLE IF EXISTS `pu_contract`;

CREATE TABLE `pu_contract` (
  `contract_id` bigint(20) NOT NULL COMMENT '合同ID',
  `contract_no` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '合同编号',
  `contract_name` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '合同名称',
  `vendor_id` bigint(20) DEFAULT NULL COMMENT '供应商ID',
  `vendor_code` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '供应商编码',
  `vendor_name` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '供应商名称',
  `contract_type` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '合同类型',
  `sign_date` datetime DEFAULT NULL COMMENT '签订日期',
  `effective_date` datetime DEFAULT NULL COMMENT '生效日期',
  `expiry_date` datetime DEFAULT NULL COMMENT '失效日期',
  `total_amount` decimal(18,4) DEFAULT NULL COMMENT '合同总金额',
  `currency` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT 'CNY' COMMENT '币种',
  `payment_terms` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '付款条款',
  `status` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT 'DRAFT' COMMENT '合同状态',
  `select_flow_id` bigint(20) DEFAULT NULL COMMENT '审批流程ID',
  `remark` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `attr1` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '扩展字段1',
  `attr2` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '扩展字段2',
  `attr3` bigint(20) DEFAULT NULL COMMENT '扩展字段3',
  `attr4` bigint(20) DEFAULT NULL COMMENT '扩展字段4',
  `tenant_id` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT '000000' COMMENT '租户编号',
  `create_dept` bigint(20) DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) DEFAULT NULL COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` bigint(20) DEFAULT NULL COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `del_flag` char(1) COLLATE utf8mb4_unicode_ci DEFAULT '0' COMMENT '删除标志',
  PRIMARY KEY (`contract_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='采购合同头表';

DROP TABLE IF EXISTS `pu_contract_line`;

CREATE TABLE `pu_contract_line` (
  `line_id` bigint(20) NOT NULL COMMENT '行ID',
  `contract_id` bigint(20) NOT NULL COMMENT '合同ID',
  `material_id` bigint(20) DEFAULT NULL COMMENT '物料ID',
  `material_code` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '物料编码',
  `material_name` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '物料名称',
  `material_spec` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '物料规格',
  `unit` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '计量单位',
  `unit_price` decimal(18,4) DEFAULT NULL COMMENT '单价',
  `quantity` decimal(18,4) DEFAULT NULL COMMENT '数量',
  `line_amount` decimal(18,4) DEFAULT NULL COMMENT '行金额',
  `delivery_date` datetime DEFAULT NULL COMMENT '交货日期',
  `sort_order` int(11) DEFAULT '0' COMMENT '排序号',
  `remark` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `attr1` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '扩展字段1',
  `attr2` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '扩展字段2',
  `attr3` bigint(20) DEFAULT NULL COMMENT '扩展字段3',
  `attr4` bigint(20) DEFAULT NULL COMMENT '扩展字段4',
  `tenant_id` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT '000000' COMMENT '租户编号',
  `create_dept` bigint(20) DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) DEFAULT NULL COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` bigint(20) DEFAULT NULL COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `del_flag` char(1) COLLATE utf8mb4_unicode_ci DEFAULT '0' COMMENT '删除标志',
  PRIMARY KEY (`line_id`) USING BTREE,
  KEY `idx_contract_id` (`contract_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='采购合同行表';

DROP TABLE IF EXISTS `rep_demo_dxtj`;

CREATE TABLE `rep_demo_dxtj` (
  `id` varchar(36) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '主键',
  `name` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '姓名',
  `gtime` datetime DEFAULT NULL COMMENT '雇佣日期',
  `update_by` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '职务',
  `jphone` varchar(125) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '家庭电话',
  `birth` datetime DEFAULT NULL COMMENT '出生日期',
  `hukou` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '户口所在地',
  `laddress` varchar(125) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '联系地址',
  `jperson` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '紧急联系人',
  `sex` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'xingbie',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;


DROP TABLE IF EXISTS `rep_demo_employee`;

CREATE TABLE `rep_demo_employee` (
  `id` varchar(10) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '主键',
  `num` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '编号',
  `name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '姓名',
  `sex` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '性别',
  `birthday` datetime DEFAULT NULL COMMENT '出生日期',
  `nation` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '民族',
  `political` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '政治面貌',
  `native_place` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '籍贯',
  `height` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '身高',
  `weight` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '体重',
  `health` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '健康状况',
  `id_card` varchar(80) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '身份证号',
  `education` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '学历',
  `school` varchar(80) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '毕业学校',
  `major` varchar(80) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '专业',
  `address` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '联系地址',
  `zip_code` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '邮编',
  `email` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Email',
  `phone` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '手机号',
  `foreign_language` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '外语语种',
  `foreign_language_level` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '外语水平',
  `computer_level` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '计算机水平',
  `graduation_time` datetime DEFAULT NULL COMMENT '毕业时间',
  `arrival_time` datetime DEFAULT NULL COMMENT '到职时间',
  `positional_titles` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '职称',
  `education_experience` mediumtext COLLATE utf8mb4_unicode_ci COMMENT '教育经历',
  `work_experience` mediumtext COLLATE utf8mb4_unicode_ci COMMENT '工作经历',
  `create_by` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '创建人',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '修改人',
  `update_time` datetime DEFAULT NULL COMMENT '修改时间',
  `del_flag` tinyint(1) DEFAULT NULL COMMENT '删除标识0-正常,1-已删除',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;


DROP TABLE IF EXISTS `rep_demo_gongsi`;

CREATE TABLE `rep_demo_gongsi` (
