DROP TABLE IF EXISTS `rep_demo_jianpiao`;

CREATE TABLE `rep_demo_jianpiao` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `bnum` varchar(125) COLLATE utf8mb4_unicode_ci NOT NULL,
  `ftime` varchar(125) COLLATE utf8mb4_unicode_ci NOT NULL,
  `sfkong` varchar(125) COLLATE utf8mb4_unicode_ci NOT NULL,
  `kaishi` varchar(125) COLLATE utf8mb4_unicode_ci NOT NULL,
