DROP TABLE IF EXISTS `rep_demo_xiaoshou`;

CREATE TABLE `rep_demo_xiaoshou` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `hnum` varchar(125) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '货品编码',
  `hname` varchar(125) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '货品名称',
  `xinghao` varchar(125) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '单位',
  `fahuocangku` varchar(125) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '数量',
  `danwei` varchar(125) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '单价',
  `num` int(11) NOT NULL COMMENT '返利',
  `danjia` varchar(125) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '备注',
  `zhekoulv` int(11) NOT NULL,
  `xiaoshoujine` varchar(125) COLLATE utf8mb4_unicode_ci NOT NULL,
  `beizhu` varchar(125) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `s_id` varchar(11) COLLATE utf8mb4_unicode_ci NOT NULL,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=19 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;


DROP TABLE IF EXISTS `sj_distributed_lock`;

CREATE TABLE `sj_distributed_lock` (
  `name` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '锁名称',
  `lock_until` timestamp(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3) COMMENT '锁定时长',
  `locked_at` timestamp(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT '锁定时间',
  `locked_by` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '锁定者',
  `create_dt` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_dt` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`name`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='锁定表';


DROP TABLE IF EXISTS `sj_group_config`;

CREATE TABLE `sj_group_config` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT COMMENT '主键',
  `namespace_id` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '764d604ec6fc45f68cd92514c40e9e1a' COMMENT '命名空间id',
  `group_name` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '组名称',
  `description` varchar(256) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '组描述',
  `token` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'SJ_cKqBTPzCsWA3VyuCfFoccmuIEGXjr5KT' COMMENT 'token',
  `group_status` tinyint(4) NOT NULL DEFAULT '0' COMMENT '组状态 0、未启用 1、启用',
  `version` int(11) NOT NULL COMMENT '版本号',
  `group_partition` int(11) NOT NULL COMMENT '分区',
  `id_generator_mode` tinyint(4) NOT NULL DEFAULT '1' COMMENT '唯一id生成模式 默认号段模式',
  `init_scene` tinyint(4) NOT NULL DEFAULT '0' COMMENT '是否初始化场景 0:否 1:是',
  `create_dt` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_dt` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uk_namespace_id_group_name` (`namespace_id`,`group_name`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='组配置';


DROP TABLE IF EXISTS `sj_job`;

CREATE TABLE `sj_job` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT COMMENT '主键',
  `namespace_id` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '764d604ec6fc45f68cd92514c40e9e1a' COMMENT '命名空间id',
  `biz_id` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `group_name` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '组名称',
  `job_name` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '名称',
  `args_str` text COLLATE utf8mb4_unicode_ci COMMENT '执行方法参数',
  `args_type` tinyint(4) NOT NULL DEFAULT '1' COMMENT '参数类型 ',
  `next_trigger_at` bigint(13) NOT NULL COMMENT '下次触发时间',
  `job_status` tinyint(4) NOT NULL DEFAULT '1' COMMENT '任务状态 0、关闭、1、开启',
  `task_type` tinyint(4) NOT NULL DEFAULT '1' COMMENT '任务类型 1、集群 2、广播 3、切片',
  `route_key` tinyint(4) NOT NULL DEFAULT '4' COMMENT '路由策略',
  `executor_type` tinyint(4) NOT NULL DEFAULT '1' COMMENT '执行器类型',
  `executor_info` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '执行器名称',
  `trigger_type` tinyint(4) NOT NULL COMMENT '触发类型 1.CRON 表达式 2. 固定时间',
  `trigger_interval` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '间隔时长',
  `block_strategy` tinyint(4) NOT NULL DEFAULT '1' COMMENT '阻塞策略 1、丢弃 2、覆盖 3、并行 4、恢复',
  `executor_timeout` int(11) NOT NULL DEFAULT '0' COMMENT '任务执行超时时间，单位秒',
  `max_retry_times` int(11) NOT NULL DEFAULT '0' COMMENT '最大重试次数',
  `parallel_num` int(11) NOT NULL DEFAULT '1' COMMENT '并行数',
  `retry_interval` int(11) NOT NULL DEFAULT '0' COMMENT '重试间隔(s)',
  `bucket_index` int(11) NOT NULL DEFAULT '0' COMMENT 'bucket',
  `resident` tinyint(4) NOT NULL DEFAULT '0' COMMENT '是否是常驻任务',
  `notify_ids` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '通知告警场景配置id列表',
  `owner_id` bigint(20) DEFAULT NULL COMMENT '负责人id',
  `labels` varchar(512) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '标签',
  `description` varchar(256) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '描述',
  `ext_attrs` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '扩展字段',
  `deleted` tinyint(4) NOT NULL DEFAULT '0' COMMENT '逻辑删除 1、删除',
  `create_dt` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_dt` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uk_sj_job_01` (`namespace_id`,`biz_id`) USING BTREE,
  KEY `idx_namespace_id_group_name` (`namespace_id`,`group_name`) USING BTREE,
  KEY `idx_job_status_bucket_index` (`job_status`,`bucket_index`) USING BTREE,
  KEY `idx_create_dt` (`create_dt`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=206 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='任务信息';


DROP TABLE IF EXISTS `sj_job_executor`;

CREATE TABLE `sj_job_executor` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT COMMENT '主键',
  `namespace_id` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '764d604ec6fc45f68cd92514c40e9e1a' COMMENT '命名空间id',
  `group_name` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '组名称',
  `executor_info` varchar(256) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '任务执行器名称',
  `executor_type` varchar(3) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '1:java 2:python 3:go',
  `create_dt` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_dt` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_namespace_id_group_name` (`namespace_id`,`group_name`) USING BTREE,
  KEY `idx_create_dt` (`create_dt`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=203 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='任务执行器信息';


DROP TABLE IF EXISTS `sj_job_log_message`;

CREATE TABLE `sj_job_log_message` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT COMMENT '主键',
  `namespace_id` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '764d604ec6fc45f68cd92514c40e9e1a' COMMENT '命名空间id',
  `group_name` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '组名称',
  `job_id` bigint(20) NOT NULL COMMENT '任务信息id',
  `task_batch_id` bigint(20) NOT NULL COMMENT '任务批次id',
  `task_id` bigint(20) NOT NULL COMMENT '调度任务id',
  `message` longtext COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '调度信息',
  `log_num` int(11) NOT NULL DEFAULT '1' COMMENT '日志数量',
  `real_time` bigint(13) NOT NULL DEFAULT '0' COMMENT '上报时间',
  `ext_attrs` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '扩展字段',
  `create_dt` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_task_batch_id_task_id` (`task_batch_id`,`task_id`) USING BTREE,
  KEY `idx_create_dt` (`create_dt`) USING BTREE,
  KEY `idx_namespace_id_group_name` (`namespace_id`,`group_name`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=48280 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='调度日志';
































































DROP TABLE IF EXISTS `sj_job_summary`;

CREATE TABLE `sj_job_summary` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT COMMENT '主键',
  `namespace_id` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '764d604ec6fc45f68cd92514c40e9e1a' COMMENT '命名空间id',
  `group_name` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '组名称',
  `business_id` bigint(20) NOT NULL COMMENT '业务id (job_id或workflow_id)',
  `system_task_type` tinyint(4) NOT NULL DEFAULT '3' COMMENT '任务类型 3、JOB任务 4、WORKFLOW任务',
  `trigger_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '统计时间',
  `success_num` int(11) NOT NULL DEFAULT '0' COMMENT '执行成功-日志数量',
  `fail_num` int(11) NOT NULL DEFAULT '0' COMMENT '执行失败-日志数量',
  `fail_reason` varchar(512) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '失败原因',
  `stop_num` int(11) NOT NULL DEFAULT '0' COMMENT '执行失败-日志数量',
