  `parent_id` bigint(20) NOT NULL DEFAULT '0' COMMENT '父执行器id',
  `task_status` tinyint(4) NOT NULL DEFAULT '0' COMMENT '执行的状态 0、失败 1、成功',
  `retry_count` int(11) NOT NULL DEFAULT '0' COMMENT '重试次数',
  `mr_stage` tinyint(4) DEFAULT NULL COMMENT '动态分片所处阶段 1:map 2:reduce 3:mergeReduce',
  `leaf` tinyint(4) NOT NULL DEFAULT '1' COMMENT '叶子节点',
  `task_name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '任务名称',
  `client_info` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '客户端地址 clientId#ip:port',
  `wf_context` text COLLATE utf8mb4_unicode_ci COMMENT '工作流全局上下文',
  `result_message` text COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '执行结果',
  `args_str` text COLLATE utf8mb4_unicode_ci COMMENT '执行方法参数',
  `args_type` tinyint(4) NOT NULL DEFAULT '1' COMMENT '参数类型 ',
  `ext_attrs` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '扩展字段',
  `create_dt` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_dt` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_task_batch_id_task_status` (`task_batch_id`,`task_status`) USING BTREE,
  KEY `idx_create_dt` (`create_dt`) USING BTREE,
  KEY `idx_namespace_id_group_name` (`namespace_id`,`group_name`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=45263 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='任务实例';































































DROP TABLE IF EXISTS `sj_job_task_batch`;

