  KEY `idx_parent_id` (`parent_id`) USING BTREE,
  KEY `idx_create_dt` (`create_dt`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='重试信息表';

