DROP TABLE IF EXISTS `wf_category`;

CREATE TABLE `wf_category` (
  `category_id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '流程分类id',
  `category_name` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '流程分类名称',
  `code` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '分类编码',
  `app_type` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '应用类型',
  `remark` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '备注',
  `create_dept` bigint(20) DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) DEFAULT NULL COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` bigint(20) DEFAULT NULL COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `del_flag` char(1) COLLATE utf8mb4_unicode_ci DEFAULT '0' COMMENT '删除标志（0代表存在 2代表删除）',
  `tenant_id` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT '000000' COMMENT '租户编号',
  PRIMARY KEY (`category_id`) USING BTREE,
  UNIQUE KEY `codeIndex` (`code`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=1807395125103874051 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='流程分类表';


DROP TABLE IF EXISTS `wf_copy`;

CREATE TABLE `wf_copy` (
  `copy_id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '抄送主键',
