  `process_id` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '流程主键',
  `process_name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '流程名称',
  `category_id` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '流程分类主键',
  `deployment_id` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '部署主键',
  `instance_id` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '流程实例主键',
  `task_id` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '任务主键',
  `user_id` bigint(20) DEFAULT NULL COMMENT '用户主键',
